{
  "name": "4컷 만화 (By Zoops)",
  "description": "어려운 모의고사 지문이나 학습 텍스트를 입력하면, 내용을 완벽하게 이해할 수 있도록 도와주는 4컷 만화 대본과 이미지를 생성합니다.",
  "requestFramePermissions": []
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import type { FullScript, Character } from '../types';
import type { ContinuationType, StoryFormat } from "../App";

if (!process.env.API_KEY) {
  throw new Error("API_KEY environment variable is not set");
}

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const scriptSchema = {
  type: Type.OBJECT,
  properties: {
    characters: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          name: { type: Type.STRING },
          description: { type: Type.STRING },
        },
        required: ["name", "description"]
      },
    },
    panels: {
      type: Type.ARRAY,
      description: "반드시 4개의 패널로 구성된 배열이어야 합니다.",
      minItems: 4,
      maxItems: 4,
      items: {
        type: Type.OBJECT,
        properties: {
          panel: { type: Type.NUMBER },
          character: { type: Type.STRING },
          description: { type: Type.STRING },
          dialogue: { type: Type.STRING },
        },
        required: ["panel", "character", "description", "dialogue"],
      },
    },
  },
  required: ["characters", "panels"],
};

const ideasSchema = {
  type: Type.OBJECT,
  properties: {
    ideas: {
      type: Type.ARRAY,
      description: "반드시 5개의 아이디어로 구성된 배열이어야 합니다.",
      minItems: 5,
      maxItems: 5,
      items: {
        type: Type.STRING,
        description: "만화 주제 아이디어"
      }
    }
  },
  required: ["ideas"]
};

const instagramPostSchema = {
  type: Type.OBJECT,
  properties: {
    description: {
      type: Type.STRING,
      description: "인스타그램 게시물을 위한 감성적이고 매력적인 설명글. 이모지를 적절히 사용해주세요."
    },
    hashtags: {
      type: Type.STRING,
      description: "해시 기호(#)로 시작하고 공백으로 구분된 관련 해시태그 문자열. (예: #공부스타그램 #모의고사 #지문이해)"
    },
  },
  required: ["description", "hashtags"],
};


function getIdeasPrompt(category: string): string {
  return `
  당신은 교육적이고 창의적인 4컷 만화 아이디어 제안 전문가입니다.
  선택된 학습 카테고리인 **'${category}'**에 맞게, 학생들이나 독자들이 복잡한 개념을 쉽게 이해할 수 있도록 돕는 재미있는 만화 주제 **5개**를 추천해주세요.

  # 규칙
  1. 각 아이디어는 한 문장으로 간결하게 표현해야 합니다.
  2. 학습 동기를 유발하거나 어려운 내용을 비유로 풀어낼 수 있는 아이디어를 제안해야 합니다.
  3. JSON 형식으로만 응답해야 합니다.
  `;
}

export async function generateIdeas(category: string): Promise<string[]> {
  const prompt = getIdeasPrompt(category);

  const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
          responseMimeType: 'application/json',
          responseSchema: ideasSchema,
      },
  });

  const jsonText = response.text.trim();
  try {
      const parsed = JSON.parse(jsonText) as { ideas: string[] };
      return parsed.ideas;
  } catch (e) {
      console.error("Failed to parse ideas JSON:", jsonText);
      throw new Error("AI가 유효하지 않은 형식의 아이디어를 생성했습니다.");
  }
}

function getScriptPrompt(topic: string, category: string, storyFormat: StoryFormat): string {
  const baseRules = `
    # 역할
    당신은 복잡하고 어려운 텍스트(모의고사 지문, 전문 서적 등)를 분석하여 핵심 내용을 4컷 만화로 완벽하게 시각화해주는 **교육 전문 만화 시나리오 작가**입니다. 
    당신의 목적은 사용자가 입력한 지문의 논리적 흐름과 핵심 주제를 만화로 구성하여 독자가 내용을 한눈에 파악하도록 돕는 것입니다.

    # 규칙
    1. **핵심 내용 반영**: 사용자가 입력한 지문("${topic}")의 핵심 키워드와 논리 구조를 4컷(기-승-전-결)에 맞춰 안배하세요.
    2. **캐릭터 설정**: 지문의 내용을 설명해주는 캐릭터(예: 척척박사, 질문 많은 학생 등)나 지문 속 핵심 주체를 의인화하여 2~3명의 캐릭터를 만드세요.
    3. **시각적 묘사(description)**: 각 컷의 'description'은 이미지 생성 AI가 지문의 추상적인 개념을 구체적인 상황으로 그릴 수 있도록 매우 자세하게 서술하세요.
    4. **대사(dialogue)**: 지문의 핵심 내용을 일상적이고 쉬운 구어체로 풀어서 작성하세요. 어려운 단어는 비유를 통해 설명하면 좋습니다.
    5. **일관성**: 캐릭터의 외형 묘사는 모든 컷에서 일관되게 유지되어야 합니다.
    6. JSON 형식으로만 응답해주세요.
  `;

  let storyFormatInstruction = '';
  if (storyFormat === 'serial') {
    storyFormatInstruction = `
    # 시리즈 형식 규칙
    입력된 지문이 매우 길거나 복잡할 경우, 이번 4컷은 이야기의 **전반부**를 다룹니다. 마지막 컷은 다음 화에서 이어질 핵심 논점이나 결론을 암시하며 마무리하세요.
    `;
  }

  let specificInstructions = '';

  switch (category) {
    case '사용자 주제에 따름':
      specificInstructions = `
        사용자가 제공한 지문을 있는 그대로 가장 정확하게 시각화하세요. 지문의 사실 관계를 왜곡하지 않고 정보를 전달하는 데 집중하세요.
      `;
      break;
    case '개념 설명 및 원리 소개':
      specificInstructions = `
        지문 속의 과학적 원리나 논리적 개념을 설명하는 데 특화된 대본을 쓰세요. 어려운 용어를 그림으로 어떻게 표현할지 고민하여 묘사하세요.
      `;
      break;
    case '언어 학습':
        specificInstructions = `
        지문에 나오는 핵심 어휘나 문법적 뉘앙스를 상황 속에서 자연스럽게 이해할 수 있도록 구성하세요.
      `;
      break;
    case '감동실화':
      specificInstructions = `
        지문의 내용이 인물이나 사건 중심이라면, 독자의 공감을 이끌어낼 수 있는 드라마틱한 연출을 가미하세요.
      `;
      break;
    case '시사 풍자 만화':
    default:
      specificInstructions = `
        지문이 사회 현상이나 시사 이슈를 다루고 있다면, 날카로운 통찰력을 담아 풍자적인 느낌으로 재구성하세요. 
        웹 검색을 통해 관련 최신 이슈를 참고하여 더 풍부한 대본을 만드세요.
      `;
      break;
  }
  return specificInstructions + storyFormatInstruction + baseRules;
}


export async function generateScript(topic: string, category: string, storyFormat: StoryFormat): Promise<FullScript> {
  const prompt = getScriptPrompt(topic, category, storyFormat);
  const isSatire = category === '시사 풍자 만화';

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const config: any = {};

  if (isSatire) {
    config.tools = [{googleSearch: {}}];
  } else {
    config.responseMimeType = 'application/json';
    config.responseSchema = scriptSchema;
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: config,
  });

  const jsonText = response.text.trim();
  try {
     let cleanJsonText = jsonText;
    if (jsonText.startsWith('```json')) {
        cleanJsonText = jsonText.substring(7, jsonText.length - 3).trim();
    } else if (jsonText.startsWith('```')) {
        cleanJsonText = jsonText.substring(3, jsonText.length - 3).trim();
    }
    return JSON.parse(cleanJsonText) as FullScript;
  } catch (e) {
    console.error("Failed to parse script JSON:", jsonText);
    throw new Error("AI가 유효하지 않은 형식의 대본을 생성했습니다.");
  }
}

function getInstagramPostPrompt(topic: string, script: FullScript): string {
  const scriptSummary = script.panels.map(p => `컷 ${p.panel}: ${p.description} ${p.dialogue}`).join('\n');

  return `
  당신은 어려운 공부 내용을 카드뉴스로 공유하는 교육 인플루언서입니다.
  아래 4컷 만화 내용을 바탕으로 학습에 도움이 되는 피드 설명을 작성하세요.

  # 만화 정보
  - 지문 주제: ${topic}
  - 내용 요약:
  ${scriptSummary}

  # 규칙
  1. **설명 (description)**:
     - "오늘의 1분 지문 정리!" 같은 컨셉으로 만화 내용을 요약하고 독자의 이해를 확인하는 질문을 던지세요.
  2. **해시태그 (hashtags)**:
     - #공부스타그램 #모의고사 #지문분석 #4컷만화 등을 포함하세요.
  3. JSON 형식으로만 응답해야 합니다.
  `;
}

export async function generateInstagramPost(topic: string, script: FullScript): Promise<{ description: string; hashtags: string; }> {
  const prompt = getInstagramPostPrompt(topic, script);

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: prompt,
    config: {
      responseMimeType: 'application/json',
      responseSchema: instagramPostSchema,
    },
  });

  const jsonText = response.text.trim();
  try {
    return JSON.parse(jsonText) as { description: string; hashtags: string; };
  } catch (e) {
    console.error("Failed to parse Instagram post JSON:", jsonText);
    throw new Error("AI가 유효하지 않은 형식의 인스타그램 포스트를 생성했습니다.");
  }
}

function getImageStylePrompt(style: string): { styleGuide: string, outputFormat: string, role: string } {
    const commonOutputFormat = `
      *   풀 컬러 디지털 일러스트레이션 (Full-color digital illustration)
      *   **텍스트 금지: 이미지 내에 글자를 넣지 마세요.**
    `;

    switch (style) {
        case '아메리칸 코믹스':
            return {
                role: "당신은 고전적인 미국 슈퍼히어로 코믹스 스타일의 전문가입니다.",
                styleGuide: `강한 외곽선, 벤데이 점(Ben-Day dots), 원색 위주의 강렬한 채색.`,
                outputFormat: commonOutputFormat
            };
        case '한국 최신 웹툰':
            return {
                role: "당신은 세련된 한국 인기 웹툰 작가입니다.",
                styleGuide: `현대적이고 매력적인 인물 디자인, 화려한 조명 효과와 그라데이션, 고퀄리티 디지털 채색.`,
                outputFormat: commonOutputFormat
            };
        case '린 클레어 (Ligne claire)':
            return {
                role: "당신은 '땡땡의 모험' 같은 라인 클레어 스타일의 대가입니다.",
                styleGuide: `일정한 두께의 깨끗한 선, 단순하고 명확한 색상 채색, 정밀한 배경 묘사.`,
                outputFormat: commonOutputFormat
            };
        case '명랑만화':
        default:
            return {
                role: "당신은 친근하고 코믹한 '명랑만화' 스타일의 전문 애니메이터입니다.",
                styleGuide: `2~3등신의 단순하고 귀여운 캐릭터, 과장된 표정, 단순하고 명확한 배경.`,
                outputFormat: commonOutputFormat
            };
    }
}


export async function generateCharacterSheet(characterDescription: string, style: string): Promise<string> {
    const { role, styleGuide, outputFormat } = getImageStylePrompt(style);

    const fullPrompt = `
    # 역할(Role)
    ${role}
    # 지시(Instruction)
    아래 설명에 맞는 캐릭터 1명의 캐릭터 시트를 생성하세요. 전신과 얼굴이 잘 보여야 합니다.
    *   캐릭터 설명: ${characterDescription}
    *   스타일 가이드: ${styleGuide}
    ${outputFormat}
    `;

  const response = await ai.models.generateImages({
    model: 'imagen-4.0-generate-001',
    prompt: fullPrompt,
    config: {
      numberOfImages: 1,
      outputMimeType: "image/png",
      aspectRatio: "1:1",
    },
  });

  if (response.generatedImages && response.generatedImages.length > 0) {
    return response.generatedImages[0].image.imageBytes;
  } else {
    throw new Error("캐릭터 시트 이미지를 생성하지 못했습니다.");
  }
}

export async function generateImage(panelDescription: string, characters: Character[], style: string): Promise<string> {
    const { role, styleGuide, outputFormat } = getImageStylePrompt(style);

    const textPrompt = `
    # 역할(Role)
    ${role}
    # 지시(Instruction)
    제공된 캐릭터 시트와 일치하는 캐릭터들이 등장하는 장면을 그리세요.
    **장면 묘사**: ${panelDescription}
    **스타일 가이드**: ${styleGuide}
    ${outputFormat}
    `;

    const imageParts = characters
        .filter(c => c.sheetImage)
        .map(c => ({
            inlineData: {
                data: c.sheetImage!,
                mimeType: 'image/png',
            },
        }));

    const response = await ai.models.generateContent({
        model: 'gemini-2.5-flash-image',
        contents: {
            parts: [
                ...imageParts,
                { text: textPrompt },
            ],
        },
        config: {
            responseModalities: [Modality.IMAGE],
        },
    });

    for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.mimeType.startsWith('image/')) {
            return part.inlineData.data;
        }
    }

    throw new Error("이미지를 생성하지 못했습니다.");
}

export async function generateContinuationScript(previousTopic: string, previousScript: FullScript, continuationTopic: string, category: string, continuationType: ContinuationType): Promise<FullScript> {
  const prompt = `
    이전 이야기에서 이어지는 교육용 만화 대본의 다음 부분을 작성하세요.
    이전 내용: ${previousTopic}
    현재 추가 지문/주제: ${continuationTopic}
    JSON 형식으로 4개의 패널을 생성하세요.
  `;

  const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
          responseMimeType: 'application/json',
          responseSchema: scriptSchema,
      },
  });

  const jsonText = response.text.trim();
  try {
      return JSON.parse(jsonText) as FullScript;
  } catch (e) {
      throw new Error("후속 대본 생성 중 오류가 발생했습니다.");
  }
}

