  const [script, setScript] = useState<FullScript | null>(null);

  const [rawImages, setRawImages] = useState<(string | null)[]>([null, null, null, null]);
  const [finalImages, setFinalImages] = useState<(string | null)[]>([null, null, null, null]);
  const [bubbleConfigs, setBubbleConfigs] = useState<(BubbleConfig | null)[]>([null, null, null, null]);

  const [isGeneratingScript, setIsGeneratingScript] = useState<boolean>(false);
  const [isGeneratingSheets, setIsGeneratingSheets] = useState<boolean>(false);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);
  const [isGeneratingAllImages, setIsGeneratingAllImages] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isGeneratingIdeas, setIsGeneratingIdeas] = useState<boolean>(false);
  const [suggestedIdeas, setSuggestedIdeas] = useState<string[]>([]);
  const [currentStep, setCurrentStep] = useState<Step>('STEP_1_TOPIC');
  const [instagramPost, setInstagramPost] = useState<{description: string; hashtags: string} | null>(null);
  const [isGeneratingPost, setIsGeneratingPost] = useState<boolean>(false);

  const [storyFormat, setStoryFormat] = useState<StoryFormat>('single');
  const [isContinuation, setIsContinuation] = useState<boolean>(false);
  const [showContinuationInput, setShowContinuationInput] = useState<boolean>(false);
  const [continuationTopic, setContinuationTopic] = useState<string>('');
  const [isGeneratingContinuation, setIsGeneratingContinuation] = useState<boolean>(false);
  const [continuationType, setContinuationType] = useState<ContinuationType>('continue');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const characterImageInputRef = useRef<HTMLInputElement>(null);
  const [uploadTargetIndex, setUploadTargetIndex] = useState<number | null>(null);
  const [regeneratingSheetIndex, setRegeneratingSheetIndex] = useState<number | null>(null);


  const handleReset = () => {
    setTopic('');
    setScript(null);
    setRawImages([null, null, null, null]);
    setFinalImages([null, null, null, null]);
    setBubbleConfigs([null, null, null, null]);
    setIsGeneratingScript(false);
    setIsGeneratingSheets(false);
    setGeneratingImageIndex(null);
    setIsGeneratingAllImages(false);
    setError(null);
    setSuggestedIdeas([]);
    setCurrentStep('STEP_1_TOPIC');
    setInstagramPost(null);
    setIsGeneratingPost(false);
    setIsContinuation(false);
    setShowContinuationInput(false);
    setContinuationTopic('');
    setIsGeneratingContinuation(false);
    setContinuationType('continue');
    setStoryFormat('single');
  };

  const handleCharacterNameChange = useCallback((characterIndex: number, newName: string) => {
    if (!script) return;
    const oldName = script.characters[characterIndex].name;
    const updatedCharacters = script.characters.map((char, index) =>
        index === characterIndex ? { ...char, name: newName } : char
    );
    const updatedPanels = script.panels.map(panel => {
        const newPanel = { ...panel };
        if (newPanel.character === oldName) newPanel.character = newName;
        if (oldName && oldName.trim() !== '' && newPanel.dialogue) {
            const escapedOldName = oldName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
            const nameRegex = new RegExp(escapedOldName, 'g');
            newPanel.dialogue = newPanel.dialogue.replace(nameRegex, newName);
        }
        return newPanel;
    });
    setScript({ ...script, characters: updatedCharacters, panels: updatedPanels });
  }, [script]);


  const handlePanelCharacterChange = useCallback((panelIndex: number, newCharacter: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, character: newCharacter };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
    setBubbleConfigs(prev => {
        const newConfigs = [...prev];
        const config = newConfigs[panelIndex];
        if (config) {
            newConfigs[panelIndex] = { ...config, style: newCharacter === '생각' ? 'thought' : 'speech' };
        }
        return newConfigs;
    });
  }, [script]);

  const handleDialogueChange = useCallback((panelIndex: number, newDialogue: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, dialogue: newDialogue };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
  }, [script]);

  const handleBubbleConfigChange = useCallback((panelIndex: number, newConfig: BubbleConfig) => {
    setBubbleConfigs(prev => {
      const newConfigs = [...prev];
      newConfigs[panelIndex] = newConfig;
      return newConfigs;
    });
  }, []);

  const handleGenerateIdeas = useCallback(async () => {
    setIsGeneratingIdeas(true);
    setError(null);
    setSuggestedIdeas([]);
    try {
      const ideas = await generateIdeas(category);
      setSuggestedIdeas(ideas);
    } catch (err) {
      setError('아이디어 추천 중 오류가 발생했습니다.');
    } finally {
      setIsGeneratingIdeas(false);
    }
  }, [category]);

  const handleGenerateScript = useCallback(async () => {
    if (!topic.trim()) {
      setError('지문 또는 학습 내용을 입력해주세요.');
      return;
    }
    setIsGeneratingScript(true);
    setError(null);
    try {
      const generatedScript = await generateScript(topic, category, storyFormat);
      setScript(generatedScript);
      setCurrentStep('STEP_2_SCRIPT');
    } catch (err) {
      setError(err instanceof Error ? err.message : '대본 생성 중 오류가 발생했습니다.');
    } finally {
      setIsGeneratingScript(false);
    }
  }, [topic, category, storyFormat]);

  const handleGenerateCharacterSheets = useCallback(async () => {
    if (!script) return;
    setIsGeneratingSheets(true);
    setError(null);
    try {
        const sheetPromises = script.characters.map(char => 
            generateCharacterSheet(char.description, artStyle)
        );
        const sheetImages = await Promise.all(sheetPromises);
        const updatedCharacters = script.characters.map((char, index) => ({
            ...char,
            sheetImage: sheetImages[index],
        }));
        setScript({ ...script, characters: updatedCharacters });
        setCurrentStep('STEP_3_CHARACTERS');
    } catch (err) {
      setError('캐릭터 생성 중 오류가 발생했습니다.');
    } finally {
        setIsGeneratingSheets(false);
    }
  }, [script, artStyle]);

  const handleRegenerateCharacterSheet = useCallback(async (characterIndex: number) => {
    if (!script) return;
    setRegeneratingSheetIndex(characterIndex);
    try {
        const charToRegenerate = script.characters[characterIndex];
        const newSheetImage = await generateCharacterSheet(charToRegenerate.description, artStyle);
        setScript(prevScript => {
            if (!prevScript) return null;
            const updatedCharacters = prevScript.characters.map((char, index) => 
                index === characterIndex ? { ...char, sheetImage: newSheetImage } : char
            );
            return { ...prevScript, characters: updatedCharacters };
        });
    } catch (err) {
        setError('이미지 재생성 실패');
    } finally {
        setRegeneratingSheetIndex(null);
    }
  }, [script, artStyle]);


  const handleGenerateImage = useCallback(async (panelIndex: number) => {
    if (!script) return;
    setGeneratingImageIndex(panelIndex);
    try {
      const panel = script.panels[panelIndex];
      const rawImageBytes = await generateImage(panel.description, script.characters, artStyle);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = rawImageBytes;
          return newImages;
        });
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${rawImageBytes}`;
        tempImg.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          if (tempCtx) {
            const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
            if (panel.character === '생각') defaultConfig.style = 'thought';
            setBubbleConfigs(prev => {
                const newConfigs = [...prev];
                newConfigs[panelIndex] = defaultConfig;
                return newConfigs;
            });
          }
        };
      } else {
        const imageWithText = await drawTextOnImage(rawImageBytes, panel, textFrameStyle);
        setFinalImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = imageWithText;
          return newImages;
        });
      }
    } catch (err) {
      setError('이미지 생성 실패');
    } finally {
      setGeneratingImageIndex(null);
    }
  }, [script, artStyle, textFrameStyle]);

  const handleGenerateInstagramPost = useCallback(async (currentTopic: string, currentScript: FullScript) => {
    setIsGeneratingPost(true);
    try {
        const post = await generateInstagramPost(currentTopic, currentScript);
        setInstagramPost(post);
    } catch (err) {} finally { setIsGeneratingPost(false); }
  }, []);

  const handleGenerateAllImages = useCallback(async () => {
    if (!script) return;
    setIsGeneratingAllImages(true);
    setError(null);
    try {
      const imageGenerationPromises = script.panels.map(panel => 
        generateImage(panel.description, script.characters, artStyle)
      );
      const generatedRawImages = await Promise.all(imageGenerationPromises);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(generatedRawImages);
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${generatedRawImages[0]}`;
        tempImg.onload = () => {
            const tempCanvas = document.createElement('canvas');
            const tempCtx = tempCanvas.getContext('2d');
            if (tempCtx) {
                const newConfigs = script.panels.map(panel => {
                    const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
                    if (panel.character === '생각') defaultConfig.style = 'thought';
                    return defaultConfig;
                });
                setBubbleConfigs(newConfigs);
            }
        };
      } else {
        const processedImages = await Promise.all(
          generatedRawImages.map((rawImg, index) => 
            drawTextOnImage(rawImg, script.panels[index], textFrameStyle)
          )
        );
        setFinalImages(processedImages);
      }
      handleGenerateInstagramPost(topic, script);
    } catch (err) {
        setError('전체 생성 실패');
    } finally {
        setIsGeneratingAllImages(false);
    }
  }, [script, artStyle, topic, handleGenerateInstagramPost, textFrameStyle]);

  const handleGenerateContinuationScript = useCallback(async () => {
    if (!script) return;
    setIsGeneratingContinuation(true);
    try {
        const newScript = await generateContinuationScript(topic, script, continuationTopic, category, continuationType);
        const updatedCharacters = newScript.characters.map(newChar => {
            const oldChar = script.characters.find(oc => oc.name === newChar.name);
            return { ...newChar, sheetImage: oldChar ? oldChar.sheetImage : null };
        });
        setScript({ ...newScript, characters: updatedCharacters });
        setTopic(continuationTopic.trim() || `${topic} (2부)`);
        setRawImages([null, null, null, null]);
        setFinalImages([null, null, null, null]);
        setBubbleConfigs([null, null, null, null]);
        setCurrentStep('STEP_2_SCRIPT');
    } catch (err) {
        setError('후속 대본 생성 실패');
    } finally { setIsGeneratingContinuation(false); }
  }, [script, topic, continuationTopic, category, continuationType]);

  const getFinalImagesForDownload = useCallback(async (): Promise<(string | null)[]> => {
    if (textFrameStyle === 'speech-bubble') {
        return await Promise.all(rawImages.map(async (rawImg, index) => {
            if (!rawImg || !script || !bubbleConfigs[index]) return null;
            return await drawTextOnImage(rawImg, script.panels[index], textFrameStyle, bubbleConfigs[index]!);
        }));
    }
    return finalImages;
  }, [rawImages, finalImages, script, bubbleConfigs, textFrameStyle]);

  const handleDownload = useCallback(async (layout: 'grid' | 'horizontal' | 'vertical') => {
    const imagesToDownload = await getFinalImagesForDownload();
    if (!imagesToDownload.every(img => img)) { setError("완성되지 않은 컷이 있습니다."); return; }
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const imageElements = await Promise.all(imagesToDownload.map(imgData => {
      return new Promise<HTMLImageElement>(res => {
        const img = new Image(); img.src = `data:image/png;base64,${imgData}`; img.onload = () => res(img);
      });
    }));
    const pw = imageElements[0].width; const ph = imageElements[0].height; const gap = 20;
    if (layout === 'grid') { canvas.width = pw * 2 + gap; canvas.height = ph * 2 + gap; }
    else if (layout === 'horizontal') { canvas.width = pw * 4 + gap * 3; canvas.height = ph; }
    else { canvas.width = pw; canvas.height = ph * 4 + gap * 3; }
    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (layout === 'grid') {
      ctx.drawImage(imageElements[0], 0, 0); ctx.drawImage(imageElements[1], pw + gap, 0);
      ctx.drawImage(imageElements[2], 0, ph + gap); ctx.drawImage(imageElements[3], pw + gap, ph + gap);
    } else if (layout === 'horizontal') {
      imageElements.forEach((img, i) => ctx.drawImage(img, i * (pw + gap), 0));
    } else {
      imageElements.forEach((img, i) => ctx.drawImage(img, 0, i * (ph + gap)));
    }
    const link = document.createElement('a'); link.download = `comic-${layout}.png`; link.href = canvas.toDataURL('image/png'); link.click();
  }, [getFinalImagesForDownload]);

  const triggerCharacterImageUpload = (index: number) => {
    setUploadTargetIndex(index); characterImageInputRef.current?.click();
  };

  const onCharacterImageSelected = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (uploadTargetIndex === null) return;
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = (reader.result as string).split(',')[1];
            setScript(prev => {
                if (!prev) return null;
                const updated = [...prev.characters];
                updated[uploadTargetIndex] = { ...updated[uploadTargetIndex], sheetImage: base64String };
                return { ...prev, characters: updated };
            });
        };
        reader.readAsDataURL(file);
    }
    setUploadTargetIndex(null);
  };

  const isBusy = isGeneratingScript || isGeneratingSheets || generatingImageIndex !== null || isGeneratingAllImages || isGeneratingIdeas || isGeneratingContinuation || regeneratingSheetIndex !== null;
  const allImagesGenerated = (rawImages.every(img => img !== null) || finalImages.every(img => img !== null));

  return (
    <div className="container mx-auto p-4 md:p-8 font-sans bg-amber-50 min-h-screen">
       <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Gugi&family=Noto+Sans+KR:wght@400;700&display=swap');
        body { font-family: 'Noto Sans KR', sans-serif; }
      `}</style>

      <input type="file" ref={characterImageInputRef} accept="image/*" className="hidden" onChange={onCharacterImageSelected} />

      <header className="text-center mb-8">
        <h1 className="text-4xl md:text-5xl font-bold text-orange-600" style={{ fontFamily: "'Gugi', cursive" }}>
          4컷 만화
        </h1>
        <p className="text-slate-600 mt-2">
          어려운 지문이나 학습 내용을 입력하세요. AI가 시각적으로 설명해줍니다.
        </p>
      </header>

      <StepIndicator currentStep={currentStep} />

      <main>
        {error && (
          <div className="max-w-2xl mx-auto my-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg text-center">
            {error}
          </div>
        )}

        {currentStep === 'STEP_1_TOPIC' && (
            <div className="max-w-2xl mx-auto p-6 bg-white rounded-xl shadow-lg border-2 border-orange-100">
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">그림 스타일</label>
                  <select value={artStyle} onChange={(e) => setArtStyle(e.target.value)} className="w-full p-3 border-2 border-orange-200 rounded-lg focus:ring-2 focus:ring-orange-400 bg-white">
                    {artStyles.map(s => <option key={s.value} value={s.value}>{s.name}</option>)}
                  </select>
                </div>
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">텍스트 박스 디자인</label>
                  <select value={textFrameStyle} onChange={(e) => setTextFrameStyle(e.target.value)} className="w-full p-3 border-2 border-orange-200 rounded-lg focus:ring-2 focus:ring-orange-400 bg-white">
                    {textFrameStyles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div className="mb-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">학습 카테고리</label>
                  <div className="flex items-center gap-2">
                      <select value={category} onChange={(e) => setCategory(e.target.value)} className="w-full p-3 border-2 border-orange-200 rounded-lg focus:ring-2 focus:ring-orange-400 bg-white">
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                      <button onClick={handleGenerateIdeas} disabled={isBusy} className="flex-shrink-0 w-14 h-14 bg-teal-500 text-white rounded-lg flex items-center justify-center text-2xl">
                          {isGeneratingIdeas ? <Spinner /> : "💡"}
                      </button>
                  </div>
                </div>

                {suggestedIdeas.length > 0 && (
                <div className="mb-4 p-4 bg-amber-100 rounded-lg border border-amber-200">
                    <h4 className="font-bold text-orange-800 mb-2 text-sm">추천 주제:</h4>
                    <div className="flex flex-wrap gap-2">
                        {suggestedIdeas.map((idea, i) => (
                            <button key={i} onClick={() => setTopic(idea)} className="text-xs px-3 py-1 bg-white rounded-full border border-orange-200 hover:bg-orange-50">{idea}</button>
                        ))}
                    </div>
                </div>
                )}

                <textarea
                value={topic}
                onChange={(e) => setTopic(e.target.value)}
                placeholder="여기에 공부할 모의고사 지문이나 어려운 텍스트를 붙여넣으세요. AI가 핵심 내용을 파악하여 만화로 그려줍니다."
                className="w-full p-3 border-2 border-orange-200 rounded-lg focus:ring-2 focus:ring-orange-400 transition resize-none"
                rows={6}
                disabled={isBusy}
                />
                <button
                onClick={handleGenerateScript}
                disabled={isBusy}
                className="w-full mt-4 px-6 py-3 bg-orange-500 text-white font-bold text-lg rounded-lg hover:bg-orange-600 transition-transform transform active:scale-95 flex items-center justify-center"
                >
                {isGeneratingScript ? <><Spinner /><span className="ml-2">지문 분석 및 대본 생성 중...</span></> : '대본 생성하기'}
                </button>
            </div>
        )}

        {currentStep === 'STEP_2_SCRIPT' && script && (
          <div className="max-w-4xl mx-auto mt-8 p-6 bg-white rounded-xl shadow-lg border-2 border-orange-100">
              <h3 className="text-2xl font-bold text-center text-orange-800 mb-6">생성된 학습 대본 확인</h3>
              <div className="space-y-6">
                {script.panels.map((p, i) => (
                    <div key={i} className="p-4 bg-amber-50 rounded-lg border-l-4 border-orange-400">
                        <p className="font-bold text-orange-700 mb-2">패널 #{p.panel}</p>
                        <p className="text-sm text-gray-700 mb-3"><span className="font-bold">시각적 설명:</span> {p.description}</p>
                        <div className="flex gap-2">
                            <input value={p.character} onChange={(e) => handlePanelCharacterChange(i, e.target.value)} className="w-24 p-2 border rounded-md font-bold text-sm" />
                            <textarea value={p.dialogue} onChange={(e) => handleDialogueChange(i, e.target.value)} className="w-full p-2 border rounded-md text-sm" rows={2} />
                        </div>
                    </div>
                ))}
              </div>
              <div className="mt-8 flex justify-center gap-4">
                  <button onClick={() => setCurrentStep('STEP_1_TOPIC')} className="px-6 py-3 bg-gray-400 text-white font-bold rounded-lg">수정하러 가기</button>
                  <button onClick={handleGenerateCharacterSheets} disabled={isBusy} className="px-6 py-3 bg-green-500 text-white font-bold rounded-lg flex items-center">
                      {isGeneratingSheets ? <><Spinner /><span className="ml-2">캐릭터 생성 중...</span></> : '캐릭터 생성하고 계속하기'}
                  </button>
              </div>
          </div>
        )}

        {currentStep === 'STEP_3_CHARACTERS' && script?.characters && (
          <div className="max-w-4xl mx-auto mt-8 p-6 bg-white rounded-xl shadow-lg border-2 border-orange-100">
            <h3 className="text-2xl font-bold text-center text-orange-800 mb-6">캐릭터 확인</h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {script.characters.map((char, i) => (
                <div key={i} className="flex flex-col items-center p-4 bg-amber-50 rounded-lg border border-orange-100">
                  {regeneratingSheetIndex === i ? <div className="w-32 h-32 flex items-center justify-center"><Spinner /></div> : (
                    <img src={`data:image/png;base64,${char.sheetImage}`} className="w-32 h-32 object-cover rounded-full border-4 border-orange-200 mb-3" />
                  )}
                  <p className="font-bold text-orange-700">{char.name}</p>
                  <div className="flex gap-2 mt-2">
                    <button onClick={() => triggerCharacterImageUpload(i)} className="text-xs p-1 bg-gray-500 text-white rounded">업로드</button>
                    <button onClick={() => handleRegenerateCharacterSheet(i)} className="text-xs p-1 bg-teal-500 text-white rounded">재생성</button>
                  </div>
                </div>
              ))}
            </div>
            <div className="mt-8 flex justify-center gap-4">
                <button onClick={handleReset} className="px-6 py-3 bg-gray-400 text-white font-bold rounded-lg">다시 시작</button>
                <button onClick={() => setCurrentStep('STEP_4_COMIC')} className="px-6 py-3 bg-green-500 text-white font-bold rounded-lg">만화 생성 시작</button>
            </div>
          </div>
        )}

        {currentStep === 'STEP_4_COMIC' && (
            <div className="max-w-4xl mx-auto mt-6">
                <button onClick={handleGenerateAllImages} disabled={isBusy || allImagesGenerated} className="px-8 py-3 bg-green-500 text-white font-bold text-lg rounded-lg mx-auto flex items-center">
                    {isGeneratingAllImages ? <><Spinner /><span className="ml-2">학습 만화 생성 중...</span></> : '모든 만화 컷 생성'}
                </button>

                <div className="mt-8 grid grid-cols-1 md:grid-cols-2 gap-4">
                    {script?.panels.map((p, i) => (
                        textFrameStyle === 'speech-bubble' && rawImages[i] ? (
                            <InteractiveComicPanel key={i} rawImage={rawImages[i]!} panel={p} bubbleConfig={bubbleConfigs[i]!} onBubbleConfigChange={(cfg) => handleBubbleConfigChange(i, cfg)} />
                        ) : (
                            <ComicPanel key={i} panel={p} imageData={finalImages[i]} isLoading={generatingImageIndex === i} onGenerateImage={() => handleGenerateImage(i)} isScriptGenerated={true} />
                        )
                    ))}
                </div>

                {allImagesGenerated && (
                    <div className="mt-10 p-6 bg-white rounded-xl shadow-lg border-2 border-orange-100 text-center">
                        <h3 className="text-xl font-bold text-orange-800 mb-4">학습 만화 저장</h3>
                        <div className="flex justify-center gap-2 flex-wrap">
                            <button onClick={() => handleDownload('grid')} className="px-4 py-2 bg-blue-500 text-white rounded-lg">바둑판형</button>
