const App: React.FC = () => {
  const [topic, setTopic] = useState<string>('');
  const [artStyle, setArtStyle] = useState<string>(artStyles[0].value);
  const [textFrameStyle, setTextFrameStyle] = useState<string>(textFrameStyles[0].id);
  const [script, setScript] = useState<FullScript | null>(null);

  const [rawImages, setRawImages] = useState<(string | null)[]>([null, null, null, null]);
  const [finalImages, setFinalImages] = useState<(string | null)[]>([null, null, null, null]);
  const [bubbleConfigs, setBubbleConfigs] = useState<(BubbleConfig | null)[]>([null, null, null, null]);

  const [isGeneratingScript, setIsGeneratingScript] = useState<boolean>(false);
  const [isGeneratingSheets, setIsGeneratingSheets] = useState<boolean>(false);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);
  const [isGeneratingAllImages, setIsGeneratingAllImages] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isGeneratingIdeas, setIsGeneratingIdeas] = useState<boolean>(false);
  const [suggestedIdeas, setSuggestedIdeas] = useState<string[]>([]);
  const [currentStep, setCurrentStep] = useState<Step>('STEP_1_TOPIC');

  const [storyFormat, setStoryFormat] = useState<StoryFormat>('single');
  const [continuationTopic, setContinuationTopic] = useState<string>('');
  const [isGeneratingContinuation, setIsGeneratingContinuation] = useState<boolean>(false);

  const characterImageInputRef = useRef<HTMLInputElement>(null);
  const [uploadTargetIndex, setUploadTargetIndex] = useState<number | null>(null);
  const [regeneratingSheetIndex, setRegeneratingSheetIndex] = useState<number | null>(null);


  const handleReset = () => {
    setTopic('');
    setScript(null);
    setRawImages([null, null, null, null]);
    setFinalImages([null, null, null, null]);
    setBubbleConfigs([null, null, null, null]);
    setIsGeneratingScript(false);
    setIsGeneratingSheets(false);
    setGeneratingImageIndex(null);
    setIsGeneratingAllImages(false);
    setError(null);
    setSuggestedIdeas([]);
    setCurrentStep('STEP_1_TOPIC');
    setContinuationTopic('');
    setIsGeneratingContinuation(false);
    setStoryFormat('single');
  };

  const handlePanelCharacterChange = useCallback((panelIndex: number, newCharacter: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, character: newCharacter };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
    setBubbleConfigs(prev => {
        const newConfigs = [...prev];
        const config = newConfigs[panelIndex];
        if (config) {
            newConfigs[panelIndex] = { ...config, style: newCharacter === '생각' ? 'thought' : 'speech' };
        }
        return newConfigs;
    });
  }, [script]);

  const handleDialogueChange = useCallback((panelIndex: number, newDialogue: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, dialogue: newDialogue };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
  }, [script]);

  const handleBubbleConfigChange = useCallback((panelIndex: number, newConfig: BubbleConfig) => {
    setBubbleConfigs(prev => {
      const newConfigs = [...prev];
      newConfigs[panelIndex] = newConfig;
      return newConfigs;
    });
  }, []);

  const handleGenerateIdeas = useCallback(async () => {
    setIsGeneratingIdeas(true);
    setError(null);
    setSuggestedIdeas([]);
    try {
      const ideas = await generateIdeas();
      setSuggestedIdeas(ideas);
    } catch (err) {
      setError('아이디어를 가져오지 못했습니다.');
    } finally {
      setIsGeneratingIdeas(false);
    }
  }, []);

  const handleGenerateScript = useCallback(async () => {
    if (!topic.trim()) {
      setError('지문이나 학습 내용을 입력해주세요.');
      return;
    }
    setIsGeneratingScript(true);
    setError(null);
    try {
      const generatedScript = await generateScript(topic, storyFormat);
      setScript(generatedScript);
      setCurrentStep('STEP_2_SCRIPT');
    } catch (err) {
      setError(err instanceof Error ? err.message : '대본 생성 중 오류가 발생했습니다.');
    } finally {
      setIsGeneratingScript(false);
    }
  }, [topic, storyFormat]);

  const handleGenerateCharacterSheets = useCallback(async () => {
    if (!script) return;
    setIsGeneratingSheets(true);
    setError(null);
    try {
        const sheetPromises = script.characters.map(char => 
            generateCharacterSheet(char.description, artStyle)
        );
        const sheetImages = await Promise.all(sheetPromises);
        const updatedCharacters = script.characters.map((char, index) => ({
            ...char,
            sheetImage: sheetImages[index],
        }));
        setScript({ ...script, characters: updatedCharacters });
        setCurrentStep('STEP_3_CHARACTERS');
    } catch (err) {
      setError('캐릭터 생성에 실패했습니다.');
    } finally {
        setIsGeneratingSheets(false);
    }
  }, [script, artStyle]);

  const handleRegenerateCharacterSheet = useCallback(async (characterIndex: number) => {
    if (!script) return;
    setRegeneratingSheetIndex(characterIndex);
    try {
        const charToRegenerate = script.characters[characterIndex];
        const newSheetImage = await generateCharacterSheet(charToRegenerate.description, artStyle);
        setScript(prevScript => {
            if (!prevScript) return null;
            const updatedCharacters = prevScript.characters.map((char, index) => 
                index === characterIndex ? { ...char, sheetImage: newSheetImage } : char
            );
            return { ...prevScript, characters: updatedCharacters };
        });
    } catch (err) {
        setError('이미지 재생성 실패');
    } finally {
        setRegeneratingSheetIndex(null);
    }
  }, [script, artStyle]);


  const handleGenerateImage = useCallback(async (panelIndex: number) => {
    if (!script) return;
    setGeneratingImageIndex(panelIndex);
    try {
      const panel = script.panels[panelIndex];
      const rawImageBytes = await generateImage(panel.description, script.characters, artStyle);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = rawImageBytes;
          return newImages;
        });
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${rawImageBytes}`;
        tempImg.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          if (tempCtx) {
            const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
            if (panel.character === '생각') defaultConfig.style = 'thought';
            setBubbleConfigs(prev => {
                const newConfigs = [...prev];
                newConfigs[panelIndex] = defaultConfig;
                return newConfigs;
            });
          }
        };
      } else {
        const imageWithText = await drawTextOnImage(rawImageBytes, panel, textFrameStyle);
        setFinalImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = imageWithText;
          return newImages;
        });
      }
    } catch (err) {
      setError('이미지 생성 실패');
    } finally {
      setGeneratingImageIndex(null);
    }
  }, [script, artStyle, textFrameStyle]);

  const handleGenerateAllImages = useCallback(async () => {
    if (!script) return;
    setIsGeneratingAllImages(true);
    setError(null);
    try {
      const imageGenerationPromises = script.panels.map(panel => 
        generateImage(panel.description, script.characters, artStyle)
      );
      const generatedRawImages = await Promise.all(imageGenerationPromises);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(generatedRawImages);
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${generatedRawImages[0]}`;
        tempImg.onload = () => {
            const tempCanvas = document.createElement('canvas');
            const tempCtx = tempCanvas.getContext('2d');
            if (tempCtx) {
                const newConfigs = script.panels.map(panel => {
                    const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
                    if (panel.character === '생각') defaultConfig.style = 'thought';
                    return defaultConfig;
                });
                setBubbleConfigs(newConfigs);
            }
        };
      } else {
        const processedImages = await Promise.all(
          generatedRawImages.map((rawImg, index) => 
            drawTextOnImage(rawImg, script.panels[index], textFrameStyle)
          )
        );
        setFinalImages(processedImages);
      }
    } catch (err) {
        setError('전체 생성 실패');
    } finally {
        setIsGeneratingAllImages(false);
    }
  }, [script, artStyle, textFrameStyle]);

  const getFinalImagesForDownload = useCallback(async (): Promise<(string | null)[]> => {
    if (textFrameStyle === 'speech-bubble') {
        return await Promise.all(rawImages.map(async (rawImg, index) => {
            if (!rawImg || !script || !bubbleConfigs[index]) return null;
            return await drawTextOnImage(rawImg, script.panels[index], textFrameStyle, bubbleConfigs[index]!);
        }));
    }
    return finalImages;
  }, [rawImages, finalImages, script, bubbleConfigs, textFrameStyle]);

  const handleDownload = useCallback(async (layout: 'grid' | 'horizontal' | 'vertical') => {
    const imagesToDownload = await getFinalImagesForDownload();
    if (!imagesToDownload.every(img => img)) { setError("완성되지 않은 컷이 있습니다."); return; }
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const imageElements = await Promise.all(imagesToDownload.map(imgData => {
      return new Promise<HTMLImageElement>(res => {
        const img = new Image(); img.src = `data:image/png;base64,${imgData}`; img.onload = () => res(img);
      });
    }));
    const pw = imageElements[0].width; const ph = imageElements[0].height; const gap = 20;
    if (layout === 'grid') { canvas.width = pw * 2 + gap; canvas.height = ph * 2 + gap; }
    else if (layout === 'horizontal') { canvas.width = pw * 4 + gap * 3; canvas.height = ph; }
    else { canvas.width = pw; canvas.height = ph * 4 + gap * 3; }
    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (layout === 'grid') {
      ctx.drawImage(imageElements[0], 0, 0); ctx.drawImage(imageElements[1], pw + gap, 0);
      ctx.drawImage(imageElements[2], 0, ph + gap); ctx.drawImage(imageElements[3], pw + gap, ph + gap);
    } else if (layout === 'horizontal') {
      imageElements.forEach((img, i) => ctx.drawImage(img, i * (pw + gap), 0));
    } else {
      imageElements.forEach((img, i) => ctx.drawImage(img, 0, i * (ph + gap)));
    }
    const link = document.createElement('a'); link.download = `comic-${layout}.png`; link.href = canvas.toDataURL('image/png'); link.click();
  }, [getFinalImagesForDownload]);

  const triggerCharacterImageUpload = (index: number) => {
    setUploadTargetIndex(index); characterImageInputRef.current?.click();
  };

  const onCharacterImageSelected = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (uploadTargetIndex === null) return;
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = (reader.result as string).split(',')[1];
            setScript(prev => {
                if (!prev) return null;
                const updated = [...prev.characters];
                updated[uploadTargetIndex] = { ...updated[uploadTargetIndex], sheetImage: base64String };
                return { ...prev, characters: updated };
            });
        };
        reader.readAsDataURL(file);
    }
    setUploadTargetIndex(null);
  };

  const isBusy = isGeneratingScript || isGeneratingSheets || generatingImageIndex !== null || isGeneratingAllImages || isGeneratingIdeas || isGeneratingContinuation || regeneratingSheetIndex !== null;
  const allImagesGenerated = (rawImages.every(img => img !== null) || finalImages.every(img => img !== null));

  return (
    <div className="container mx-auto p-4 md:p-8 min-h-screen text-slate-800">
      <input type="file" ref={characterImageInputRef} accept="image/*" className="hidden" onChange={onCharacterImageSelected} />

      <header className="text-center mb-12">
        <h1 className="text-5xl md:text-7xl font-title text-orange-500 mb-4 tracking-tight">
          4컷 만화
        </h1>
        <p className="text-slate-500 text-lg font-medium">
          어려운 지문이나 학습 내용을 시각적으로 풀어내는 AI 도구
        </p>
      </header>

      <StepIndicator currentStep={currentStep} />

      <main className="max-w-4xl mx-auto">
        {error && (
          <div className="my-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-center font-medium shadow-sm animate-pulse">
            ⚠️ {error}
          </div>
        )}

        {currentStep === 'STEP_1_TOPIC' && (
            <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 p-8 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2 px-1">그림 스타일</label>
                    <select value={artStyle} onChange={(e) => setArtStyle(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-orange-400 text-slate-700 appearance-none cursor-pointer">
                      {artStyles.map(s => <option key={s.value} value={s.value}>{s.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2 px-1">텍스트 디자인</label>
                    <select value={textFrameStyle} onChange={(e) => setTextFrameStyle(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-orange-400 text-slate-700 appearance-none cursor-pointer">
                      {textFrameStyles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex justify-between items-end">
                    <label className="block text-sm font-bold text-slate-700 px-1">학습 지문 입력</label>
                    <button onClick={handleGenerateIdeas} disabled={isBusy} className="text-sm font-bold text-teal-600 hover:text-teal-700 flex items-center gap-1.5 transition-colors">
                        {isGeneratingIdeas ? <Spinner /> : "💡 구성 아이디어 추천"}
                    </button>
                  </div>

                  {suggestedIdeas.length > 0 && (
                    <div className="p-4 bg-teal-50/50 rounded-2xl border border-teal-100 flex flex-wrap gap-2">
                        {suggestedIdeas.map((idea, i) => (
                            <button key={i} onClick={() => setTopic(idea)} className="text-xs px-3 py-1.5 bg-white text-teal-700 rounded-full border border-teal-100 hover:border-teal-300 hover:shadow-sm transition-all">{idea}</button>
                        ))}
                    </div>
                  )}

                  <textarea
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                    placeholder="모의고사 지문이나 어려운 텍스트를 이곳에 붙여넣으세요. AI가 핵심 내용을 파악하여 만화로 그려줍니다."
                    className="w-full p-6 bg-slate-50 border-none rounded-3xl focus:ring-2 focus:ring-orange-400 transition-all resize-none min-h-[200px] text-slate-700 leading-relaxed placeholder:text-slate-400"
                    disabled={isBusy}
                  />
                </div>

                <button
                  onClick={handleGenerateScript}
                  disabled={isBusy}
                  className="w-full py-5 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black text-xl rounded-2xl shadow-lg shadow-orange-200 hover:shadow-orange-300 transition-all transform hover:-translate-y-1 active:translate-y-0 disabled:grayscale flex items-center justify-center gap-3"
                >
                  {isGeneratingScript ? <Spinner /> : '🚀 학습 대본 생성하기'}
                </button>
            </div>
        )}

        {currentStep === 'STEP_2_SCRIPT' && script && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h3 className="text-3xl font-title text-slate-800 text-center">대본 검토</h3>
              <div className="grid gap-6">
                {script.panels.map((p, i) => (
                    <div key={i} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 group transition-all hover:border-orange-200">
                        <div className="flex justify-between items-center mb-4">
                          <span className="px-3 py-1 bg-orange-100 text-orange-600 text-xs font-black rounded-full uppercase tracking-widest">Panel {p.panel}</span>
                        </div>
                        <p className="text-sm text-slate-500 mb-4 bg-white p-4 rounded-2xl border border-slate-100 leading-relaxed">
                          <strong className="text-slate-700 mr-2">이미지 가이드:</strong> {p.description}
                        </p>
                        <div className="flex gap-4">
                            <input value={p.character} onChange={(e) => handlePanelCharacterChange(i, e.target.value)} className="w-32 p-3 bg-white border-none rounded-xl font-bold text-sm focus:ring-2 focus:ring-orange-400 shadow-sm" placeholder="화자" />
                            <textarea value={p.dialogue} onChange={(e) => handleDialogueChange(i, e.target.value)} className="w-full p-3 bg-white border-none rounded-xl text-sm focus:ring-2 focus:ring-orange-400 shadow-sm" rows={2} placeholder="대사" />
                        </div>
                    </div>
                ))}
              </div>
              <div className="flex flex-col md:flex-row gap-4 pt-4">
                  <button onClick={() => setCurrentStep('STEP_1_TOPIC')} className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-all">수정하기</button>
                  <button onClick={handleGenerateCharacterSheets} disabled={isBusy} className="flex-[2] py-4 bg-orange-500 text-white font-black rounded-2xl shadow-lg shadow-orange-200 flex items-center justify-center gap-2">
                      {isGeneratingSheets ? <Spinner /> : '🎨 캐릭터 일러스트 생성'}
                  </button>
              </div>
          </div>
        )}

        {currentStep === 'STEP_3_CHARACTERS' && script?.characters && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 space-y-10 animate-in fade-in zoom-in duration-500">
            <h3 className="text-3xl font-title text-slate-800 text-center">학습 만화 주인공</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-8">
              {script.characters.map((char, i) => (
                <div key={i} className="flex flex-col items-center group">
                  <div className="relative w-40 h-40 mb-6 group">
                    <div className="absolute inset-0 bg-orange-500 rounded-full blur-xl opacity-0 group-hover:opacity-20 transition-opacity"></div>
                    {regeneratingSheetIndex === i ? (
                      <div className="w-full h-full bg-slate-50 rounded-full flex items-center justify-center border-4 border-slate-100"><Spinner /></div>
                    ) : (
                      <img src={`data:image/png;base64,${char.sheetImage}`} className="w-full h-full object-cover rounded-full border-4 border-white shadow-xl transition-transform group-hover:scale-105" />
                    )}
                  </div>
                  <h4 className="font-black text-xl text-slate-800 mb-4">{char.name}</h4>
                  <div className="flex gap-2">
                    <button onClick={() => triggerCharacterImageUpload(i)} className="text-[10px] uppercase font-black tracking-widest px-3 py-1.5 bg-slate-100 text-slate-500 rounded-full hover:bg-slate-200">Upload</button>
                    <button onClick={() => handleRegenerateCharacterSheet(i)} className="text-[10px] uppercase font-black tracking-widest px-3 py-1.5 bg-teal-500 text-white rounded-full hover:bg-teal-600 shadow-sm shadow-teal-100">Redraw</button>
                  </div>
                </div>
              ))}
            </div>
            <div className="flex gap-4 border-t border-slate-100 pt-10">
                <button onClick={handleReset} className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl">다시 하기</button>
                <button onClick={() => setCurrentStep('STEP_4_COMIC')} className="flex-[2] py-4 bg-orange-500 text-white font-black rounded-2xl shadow-lg shadow-orange-100">만화 컷 렌더링 시작</button>
            </div>
          </div>
        )}

        {currentStep === 'STEP_4_COMIC' && (
            <div className="space-y-8 animate-in fade-in duration-700">
                <div className="flex justify-center">
                  <button onClick={handleGenerateAllImages} disabled={isBusy || allImagesGenerated} className="px-10 py-5 bg-gradient-to-r from-teal-500 to-emerald-500 text-white font-black text-xl rounded-2xl shadow-xl shadow-teal-200 hover:scale-105 transition-all disabled:scale-100 disabled:grayscale">
                      {isGeneratingAllImages ? <><Spinner /><span className="ml-3">만화 완성 중...</span></> : '✨ 전체 4컷 생성'}
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {script?.panels.map((p, i) => (
                        <div key={i} className="group transition-all">
                          {textFrameStyle === 'speech-bubble' && rawImages[i] ? (
                              <InteractiveComicPanel rawImage={rawImages[i]!} panel={p} bubbleConfig={bubbleConfigs[i]!} onBubbleConfigChange={(cfg) => handleBubbleConfigChange(i, cfg)} />
                          ) : (
                              <ComicPanel panel={p} imageData={finalImages[i]} isLoading={generatingImageIndex === i} onGenerateImage={() => handleGenerateImage(i)} isScriptGenerated={true} />
                          )}
                        </div>
                    ))}
                </div>

                {allImagesGenerated && (
                    <div className="bg-white rounded-3xl p-10 shadow-2xl border border-slate-100 text-center space-y-6 animate-in slide-in-from-top-4 duration-500">
                        <h3 className="text-3xl font-title text-slate-800">🎉 학습 만화가 완성되었습니다!</h3>
                        <div className="flex justify-center gap-4 flex-wrap">
                            <button onClick={() => handleDownload('grid')} className="px-6 py-3 bg-slate-800 text-white font-bold rounded-xl hover:bg-black transition-colors">🖼️ 바둑판 저장</button>
                            <button onClick={() => handleDownload('vertical')} className="px-6 py-3 bg-slate-800 text-white font-bold rounded-xl hover:bg-black transition-colors">📱 모바일용 저장</button>
                            <button onClick={handleReset} className="px-6 py-3 bg-slate-200 text-slate-700 font-bold rounded-xl hover:bg-slate-300 transition-colors">처음부터 다시</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </main>

      <footer className="text-center mt-20 pt-10 border-t border-slate-100">
        <p className="text-slate-400 font-bold tracking-tight mb-2">Developed by <span className="text-orange-500">Zoops</span></p>
        <p className="text-xs text-slate-300">© 2025 AI Study Comic Tool. All Rights Reserved.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { generateScript, generateImage, generateCharacterSheet, generateIdeas, generateInstagramPost, generateContinuationScript } from './services/geminiService';
import type { FullScript, Character } from './types';
import ComicPanel from './components/ComicPanel';
import Spinner from './components/Spinner';
import { InteractiveComicPanel, type BubbleConfig, drawTextOnImage, getDefaultBubbleConfig } from './components/InteractiveComicPanel';

// window.aistudio types for TypeScript
declare global {
  interface Window {
    aistudio: {
      hasSelectedApiKey: () => Promise<boolean>;
      openSelectKey: () => Promise<void>;
    };
  }
}

const artStyles = [
  { name: '🧸 명랑만화', value: '명랑만화' },
  { name: '💥 아메리칸 코믹스', value: '아메리칸 코믹스' },
  { name: '✨ 한국 최신 웹툰', value: '한국 최신 웹툰' },
  { name: '🎞️ 린 클레어 (복고풍)', value: '린 클레어 (Ligne claire)' },
];

const textFrameStyles = [
  { id: 'speech-bubble', name: '💬 말풍선 (자유 편집)' },
  { id: 'simple', name: '⬜ 심플 (하단 흰색)' },
  { id: 'webtoon', name: '📱 웹툰 스타일' },
  { id: 'narration', name: '📜 나레이션 (상단)' },
  { id: 'cinematic', name: '🎬 시네마틱 자막' },
];

type Step = 'STEP_1_TOPIC' | 'STEP_2_SCRIPT' | 'STEP_3_CHARACTERS' | 'STEP_4_COMIC';
export type TailDirection =
  | 'top-left' | 'top-center' | 'top-right'
  | 'bottom-left' | 'bottom-center' | 'bottom-right'
  | 'left-top' | 'left-center' | 'left-bottom'
  | 'right-top' | 'right-center' | 'right-bottom';
export type StoryFormat = 'single' | 'serial';
export type ContinuationType = 'continue' | 'end';


const StepIndicator: React.FC<{ currentStep: Step }> = ({ currentStep }) => {
    const steps = [
        { id: 'STEP_1_TOPIC', title: '지문 입력' },
        { id: 'STEP_2_SCRIPT', title: '대본 확인' },
        { id: 'STEP_3_CHARACTERS', title: '캐릭터 생성' },
        { id: 'STEP_4_COMIC', title: '만화 완성' }
    ];
    const currentStepIndex = steps.findIndex(s => s.id === currentStep);

    return (
        <div className="flex justify-center items-center my-10 w-full max-w-2xl mx-auto px-4">
            {steps.map((step, index) => (
                <React.Fragment key={step.id}>
                    <div className="flex flex-col items-center relative">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 ${index <= currentStepIndex ? 'bg-orange-500 text-white shadow-lg scale-110' : 'bg-slate-200 text-slate-500'}`}>
                            {index + 1}
                        </div>
                        <span className={`absolute -bottom-7 whitespace-nowrap text-xs font-semibold transition-colors duration-300 ${index <= currentStepIndex ? 'text-orange-600' : 'text-slate-400'}`}>{step.title}</span>
                    </div>
                    {index < steps.length - 1 && (
                        <div className={`flex-1 h-0.5 mx-2 transition-colors duration-500 ${index < currentStepIndex ? 'bg-orange-500' : 'bg-slate-200'}`}></div>
                    )}
                </React.Fragment>
            ))}
        </div>
    );
};

const App: React.FC = () => {
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);
  const [topic, setTopic] = useState<string>('');
  const [artStyle, setArtStyle] = useState<string>(artStyles[0].value);
  const [textFrameStyle, setTextFrameStyle] = useState<string>(textFrameStyles[0].id);
  const [script, setScript] = useState<FullScript | null>(null);

  const [rawImages, setRawImages] = useState<(string | null)[]>([null, null, null, null]);
  const [finalImages, setFinalImages] = useState<(string | null)[]>([null, null, null, null]);
  const [bubbleConfigs, setBubbleConfigs] = useState<(BubbleConfig | null)[]>([null, null, null, null]);

  const [isGeneratingScript, setIsGeneratingScript] = useState<boolean>(false);
  const [isGeneratingSheets, setIsGeneratingSheets] = useState<boolean>(false);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);
  const [isGeneratingAllImages, setIsGeneratingAllImages] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isGeneratingIdeas, setIsGeneratingIdeas] = useState<boolean>(false);
  const [suggestedIdeas, setSuggestedIdeas] = useState<string[]>([]);
  const [currentStep, setCurrentStep] = useState<Step>('STEP_1_TOPIC');

  const [storyFormat, setStoryFormat] = useState<StoryFormat>('single');
  const [continuationTopic, setContinuationTopic] = useState<string>('');
  const [isGeneratingContinuation, setIsGeneratingContinuation] = useState<boolean>(false);

  const characterImageInputRef = useRef<HTMLInputElement>(null);
  const [uploadTargetIndex, setUploadTargetIndex] = useState<number | null>(null);
  const [regeneratingSheetIndex, setRegeneratingSheetIndex] = useState<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        // Fallback for non-AI Studio environments
        setHasApiKey(true);
      }
    };
    checkKey();
  }, []);

  const handleConnectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Assume selection successful as per guidelines to avoid race conditions
      setHasApiKey(true);
    }
  };

  const handleReset = () => {
    setTopic('');
    setScript(null);
    setRawImages([null, null, null, null]);
    setFinalImages([null, null, null, null]);
    setBubbleConfigs([null, null, null, null]);
    setIsGeneratingScript(false);
    setIsGeneratingSheets(false);
    setGeneratingImageIndex(null);
    setIsGeneratingAllImages(false);
    setError(null);
    setSuggestedIdeas([]);
    setCurrentStep('STEP_1_TOPIC');
    setContinuationTopic('');
    setIsGeneratingContinuation(false);
    setStoryFormat('single');
  };

  const handlePanelCharacterChange = useCallback((panelIndex: number, newCharacter: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, character: newCharacter };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
    setBubbleConfigs(prev => {
        const newConfigs = [...prev];
        const config = newConfigs[panelIndex];
        if (config) {
            newConfigs[panelIndex] = { ...config, style: newCharacter === '생각' ? 'thought' : 'speech' };
        }
        return newConfigs;
    });
  }, [script]);

  const handleDialogueChange = useCallback((panelIndex: number, newDialogue: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, dialogue: newDialogue };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
  }, [script]);

  const handleBubbleConfigChange = useCallback((panelIndex: number, newConfig: BubbleConfig) => {
    setBubbleConfigs(prev => {
      const newConfigs = [...prev];
      newConfigs[panelIndex] = newConfig;
      return newConfigs;
    });
  }, []);

  const handleGenerateIdeas = useCallback(async () => {
    setIsGeneratingIdeas(true);
    setError(null);
    setSuggestedIdeas([]);
    try {
      const ideas = await generateIdeas();
      setSuggestedIdeas(ideas);
    } catch (err) {
      setError('아이디어를 가져오지 못했습니다.');
    } finally {
      setIsGeneratingIdeas(false);
    }
  }, []);

  const handleGenerateScript = useCallback(async () => {
    if (!topic.trim()) {
      setError('지문이나 학습 내용을 입력해주세요.');
      return;
    }
    setIsGeneratingScript(true);
    setError(null);
    try {
      const generatedScript = await generateScript(topic, storyFormat);
      setScript(generatedScript);
      setCurrentStep('STEP_2_SCRIPT');
    } catch (err) {
      if (err instanceof Error && err.message.includes("Requested entity was not found")) {
        setHasApiKey(false);
      }
      setError(err instanceof Error ? err.message : '대본 생성 중 오류가 발생했습니다.');
    } finally {
      setIsGeneratingScript(false);
    }
  }, [topic, storyFormat]);

  const handleGenerateCharacterSheets = useCallback(async () => {
    if (!script) return;
    setIsGeneratingSheets(true);
    setError(null);
    try {
        const sheetPromises = script.characters.map(char => 
            generateCharacterSheet(char.description, artStyle)
        );
        const sheetImages = await Promise.all(sheetPromises);
        const updatedCharacters = script.characters.map((char, index) => ({
            ...char,
            sheetImage: sheetImages[index],
        }));
        setScript({ ...script, characters: updatedCharacters });
        setCurrentStep('STEP_3_CHARACTERS');
    } catch (err) {
      if (err instanceof Error && err.message.includes("Requested entity was not found")) {
        setHasApiKey(false);
      }
      setError('캐릭터 생성에 실패했습니다.');
    } finally {
        setIsGeneratingSheets(false);
    }
  }, [script, artStyle]);

  const handleRegenerateCharacterSheet = useCallback(async (characterIndex: number) => {
    if (!script) return;
    setRegeneratingSheetIndex(characterIndex);
    try {
        const charToRegenerate = script.characters[characterIndex];
        const newSheetImage = await generateCharacterSheet(charToRegenerate.description, artStyle);
        setScript(prevScript => {
            if (!prevScript) return null;
            const updatedCharacters = prevScript.characters.map((char, index) => 
                index === characterIndex ? { ...char, sheetImage: newSheetImage } : char
            );
            return { ...prevScript, characters: updatedCharacters };
        });
    } catch (err) {
        setError('이미지 재생성 실패');
    } finally {
        setRegeneratingSheetIndex(null);
    }
  }, [script, artStyle]);


  const handleGenerateImage = useCallback(async (panelIndex: number) => {
    if (!script) return;
    setGeneratingImageIndex(panelIndex);
    try {
      const panel = script.panels[panelIndex];
      const rawImageBytes = await generateImage(panel.description, script.characters, artStyle);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = rawImageBytes;
          return newImages;
        });
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${rawImageBytes}`;
        tempImg.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          if (tempCtx) {
            const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
            if (panel.character === '생각') defaultConfig.style = 'thought';
            setBubbleConfigs(prev => {
                const newConfigs = [...prev];
                newConfigs[panelIndex] = defaultConfig;
                return newConfigs;
            });
          }
        };
      } else {
        const imageWithText = await drawTextOnImage(rawImageBytes, panel, textFrameStyle);
        setFinalImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = imageWithText;
          return newImages;
        });
      }
    } catch (err) {
      setError('이미지 생성 실패');
    } finally {
      setGeneratingImageIndex(null);
    }
  }, [script, artStyle, textFrameStyle]);

  const handleGenerateAllImages = useCallback(async () => {
    if (!script) return;
    setIsGeneratingAllImages(true);
    setError(null);
    try {
      const imageGenerationPromises = script.panels.map(panel => 
        generateImage(panel.description, script.characters, artStyle)
      );
      const generatedRawImages = await Promise.all(imageGenerationPromises);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(generatedRawImages);
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${generatedRawImages[0]}`;
        tempImg.onload = () => {
            const tempCanvas = document.createElement('canvas');
            const tempCtx = tempCanvas.getContext('2d');
            if (tempCtx) {
                const newConfigs = script.panels.map(panel => {
                    const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
                    if (panel.character === '생각') defaultConfig.style = 'thought';
                    return defaultConfig;
                });
                setBubbleConfigs(newConfigs);
            }
        };
      } else {
        const processedImages = await Promise.all(
          generatedRawImages.map((rawImg, index) => 
            drawTextOnImage(rawImg, script.panels[index], textFrameStyle)
          )
        );
        setFinalImages(processedImages);
      }
    } catch (err) {
        setError('전체 생성 실패');
    } finally {
        setIsGeneratingAllImages(false);
    }
  }, [script, artStyle, textFrameStyle]);

  const getFinalImagesForDownload = useCallback(async (): Promise<(string | null)[]> => {
    if (textFrameStyle === 'speech-bubble') {
        return await Promise.all(rawImages.map(async (rawImg, index) => {
            if (!rawImg || !script || !bubbleConfigs[index]) return null;
            return await drawTextOnImage(rawImg, script.panels[index], textFrameStyle, bubbleConfigs[index]!);
        }));
    }
    return finalImages;
  }, [rawImages, finalImages, script, bubbleConfigs, textFrameStyle]);

  const handleDownload = useCallback(async (layout: 'grid' | 'horizontal' | 'vertical') => {
    const imagesToDownload = await getFinalImagesForDownload();
    if (!imagesToDownload.every(img => img)) { setError("완성되지 않은 컷이 있습니다."); return; }
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const imageElements = await Promise.all(imagesToDownload.map(imgData => {
      return new Promise<HTMLImageElement>(res => {
        const img = new Image(); img.src = `data:image/png;base64,${imgData}`; img.onload = () => res(img);
      });
    }));
    const pw = imageElements[0].width; const ph = imageElements[0].height; const gap = 20;
    if (layout === 'grid') { canvas.width = pw * 2 + gap; canvas.height = ph * 2 + gap; }
    else if (layout === 'horizontal') { canvas.width = pw * 4 + gap * 3; canvas.height = ph; }
    else { canvas.width = pw; canvas.height = ph * 4 + gap * 3; }
    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (layout === 'grid') {
      ctx.drawImage(imageElements[0], 0, 0); ctx.drawImage(imageElements[1], pw + gap, 0);
      ctx.drawImage(imageElements[2], 0, ph + gap); ctx.drawImage(imageElements[3], pw + gap, ph + gap);
    } else if (layout === 'horizontal') {
      imageElements.forEach((img, i) => ctx.drawImage(img, i * (pw + gap), 0));
    } else {
      imageElements.forEach((img, i) => ctx.drawImage(img, 0, i * (ph + gap)));
    }
    const link = document.createElement('a'); link.download = `comic-${layout}.png`; link.href = canvas.toDataURL('image/png'); link.click();
  }, [getFinalImagesForDownload]);

  const triggerCharacterImageUpload = (index: number) => {
    setUploadTargetIndex(index); characterImageInputRef.current?.click();
  };

  const onCharacterImageSelected = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (uploadTargetIndex === null) return;
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = (reader.result as string).split(',')[1];
            setScript(prev => {
                if (!prev) return null;
                const updated = [...prev.characters];
                updated[uploadTargetIndex] = { ...updated[uploadTargetIndex], sheetImage: base64String };
                return { ...prev, characters: updated };
            });
        };
        reader.readAsDataURL(file);
    }
    setUploadTargetIndex(null);
  };

  if (hasApiKey === null) {
    return <div className="flex items-center justify-center min-h-screen bg-[#f8fafc]"><Spinner /></div>;
  }

  if (hasApiKey === false) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-[#f8fafc] p-6 text-center">
        <div className="bg-white p-12 rounded-[40px] shadow-2xl shadow-slate-200 border border-slate-100 max-w-lg animate-in fade-in zoom-in duration-500">
          <h1 className="text-5xl font-title text-orange-500 mb-6 tracking-tight">4컷 만화</h1>
          <p className="text-slate-600 mb-8 leading-relaxed">
            고품질 이미지 생성(Imagen 4)을 위해<br />
            <strong>결제가 설정된 Google Cloud 프로젝트</strong>의 API 키가 필요합니다.
          </p>
          <button 
            onClick={handleConnectKey}
            className="w-full py-5 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black text-xl rounded-2xl shadow-lg shadow-orange-200 hover:scale-105 transition-transform mb-6"
          >
            Google API 키 연결하기
          </button>
          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-orange-500 text-sm font-bold hover:underline"
          >
            결제 및 API 키 설정 도움말 보기
          </a>
        </div>
      </div>
    );
  }

  const isBusy = isGeneratingScript || isGeneratingSheets || generatingImageIndex !== null || isGeneratingAllImages || isGeneratingIdeas || isGeneratingContinuation || regeneratingSheetIndex !== null;
  const allImagesGenerated = (rawImages.every(img => img !== null) || finalImages.every(img => img !== null));

  return (
    <div className="container mx-auto p-4 md:p-8 min-h-screen text-slate-800">
      <input type="file" ref={characterImageInputRef} accept="image/*" className="hidden" onChange={onCharacterImageSelected} />

      <header className="text-center mb-12">
        <h1 className="text-5xl md:text-7xl font-title text-orange-500 mb-4 tracking-tight">
          4컷 만화
        </h1>
        <p className="text-slate-500 text-lg font-medium">
          어려운 지문이나 학습 내용을 시각적으로 풀어내는 AI 도구
        </p>
      </header>

      <StepIndicator currentStep={currentStep} />

      <main className="max-w-4xl mx-auto">
        {error && (
          <div className="my-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-center font-medium shadow-sm animate-pulse">
            ⚠️ {error}
          </div>
        )}

        {currentStep === 'STEP_1_TOPIC' && (
            <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 p-8 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2 px-1">그림 스타일</label>
                    <select value={artStyle} onChange={(e) => setArtStyle(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-orange-400 text-slate-700 appearance-none cursor-pointer">
                      {artStyles.map(s => <option key={s.value} value={s.value}>{s.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2 px-1">텍스트 디자인</label>
                    <select value={textFrameStyle} onChange={(e) => setTextFrameStyle(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-orange-400 text-slate-700 appearance-none cursor-pointer">
                      {textFrameStyles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex justify-between items-end">
                    <label className="block text-sm font-bold text-slate-700 px-1">학습 지문 입력</label>
                    <button onClick={handleGenerateIdeas} disabled={isBusy} className="text-sm font-bold text-teal-600 hover:text-teal-700 flex items-center gap-1.5 transition-colors">
                        {isGeneratingIdeas ? <Spinner /> : "💡 구성 아이디어 추천"}
                    </button>
                  </div>

                  {suggestedIdeas.length > 0 && (
                    <div className="p-4 bg-teal-50/50 rounded-2xl border border-teal-100 flex flex-wrap gap-2">
                        {suggestedIdeas.map((idea, i) => (
                            <button key={i} onClick={() => setTopic(idea)} className="text-xs px-3 py-1.5 bg-white text-teal-700 rounded-full border border-teal-100 hover:border-teal-300 hover:shadow-sm transition-all">{idea}</button>
                        ))}
                    </div>
                  )}

                  <textarea
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                    placeholder="모의고사 지문이나 어려운 텍스트를 이곳에 붙여넣으세요. AI가 핵심 내용을 파악하여 만화로 그려줍니다."
                    className="w-full p-6 bg-slate-50 border-none rounded-3xl focus:ring-2 focus:ring-orange-400 transition-all resize-none min-h-[200px] text-slate-700 leading-relaxed placeholder:text-slate-400"
                    disabled={isBusy}
                  />
                </div>

                <button
                  onClick={handleGenerateScript}
                  disabled={isBusy}
                  className="w-full py-5 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black text-xl rounded-2xl shadow-lg shadow-orange-200 hover:shadow-orange-300 transition-all transform hover:-translate-y-1 active:translate-y-0 disabled:grayscale flex items-center justify-center gap-3"
                >
                  {isGeneratingScript ? <Spinner /> : '🚀 학습 대본 생성하기'}
                </button>
            </div>
        )}

        {currentStep === 'STEP_2_SCRIPT' && script && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h3 className="text-3xl font-title text-slate-800 text-center">대본 검토</h3>
              <div className="grid gap-6">
                {script.panels.map((p, i) => (
                    <div key={i} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 group transition-all hover:border-orange-200">
                        <div className="flex justify-between items-center mb-4">
                          <span className="px-3 py-1 bg-orange-100 text-orange-600 text-xs font-black rounded-full uppercase tracking-widest">Panel {p.panel}</span>
                        </div>
                        <p className="text-sm text-slate-500 mb-4 bg-white p-4 rounded-2xl border border-slate-100 leading-relaxed">
                          <strong className="text-slate-700 mr-2">이미지 가이드:</strong> {p.description}
                        </p>
                        <div className="flex gap-4">
                            <input value={p.character} onChange={(e) => handlePanelCharacterChange(i, e.target.value)} className="w-32 p-3 bg-white border-none rounded-xl font-bold text-sm focus:ring-2 focus:ring-orange-400 shadow-sm" placeholder="화자" />
                            <textarea value={p.dialogue} onChange={(e) => handleDialogueChange(i, e.target.value)} className="w-full p-3 bg-white border-none rounded-xl text-sm focus:ring-2 focus:ring-orange-400 shadow-sm" rows={2} placeholder="대사" />
                        </div>
                    </div>
                ))}
              </div>
              <div className="flex flex-col md:flex-row gap-4 pt-4">
                  <button onClick={() => setCurrentStep('STEP_1_TOPIC')} className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-all">수정하기</button>
                  <button onClick={handleGenerateCharacterSheets} disabled={isBusy} className="flex-[2] py-4 bg-orange-500 text-white font-black rounded-2xl shadow-lg shadow-orange-200 flex items-center justify-center gap-2">
                      {isGeneratingSheets ? <Spinner /> : '🎨 캐릭터 일러스트 생성'}
                  </button>
              </div>
          </div>
        )}

        {currentStep === 'STEP_3_CHARACTERS' && script?.characters && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 space-y-10 animate-in fade-in zoom-in duration-500">
            <h3 className="text-3xl font-title text-slate-800 text-center">학습 만화 주인공</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-8">
              {script.characters.map((char, i) => (
                <div key={i} className="flex flex-col items-center group">
                  <div className="relative w-40 h-40 mb-6 group">
                    <div className="absolute inset-0 bg-orange-500 rounded-full blur-xl opacity-0 group-hover:opacity-20 transition-opacity"></div>
                    {regeneratingSheetIndex === i ? (
                      <div className="w-full h-full bg-slate-50 rounded-full flex items-center justify-center border-4 border-slate-100"><Spinner /></div>
                    ) : (
                      <img src={`data:image/png;base64,${char.sheetImage}`} className="w-full h-full object-cover rounded-full border-4 border-white shadow-xl transition-transform group-hover:scale-105" />
                    )}
                  </div>
                  <h4 className="font-black text-xl text-slate-800 mb-4">{char.name}</h4>
                  <div className="flex gap-2">
                    <button onClick={() => triggerCharacterImageUpload(i)} className="text-[10px] uppercase font-black tracking-widest px-3 py-1.5 bg-slate-100 text-slate-500 rounded-full hover:bg-slate-200">Upload</button>
                    <button onClick={() => handleRegenerateCharacterSheet(i)} className="text-[10px] uppercase font-black tracking-widest px-3 py-1.5 bg-teal-500 text-white rounded-full hover:bg-teal-600 shadow-sm shadow-teal-100">Redraw</button>
                  </div>
                </div>
              ))}
            </div>
            <div className="flex gap-4 border-t border-slate-100 pt-10">
                <button onClick={handleReset} className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl">다시 하기</button>
                <button onClick={() => setCurrentStep('STEP_4_COMIC')} className="flex-[2] py-4 bg-orange-500 text-white font-black rounded-2xl shadow-lg shadow-orange-100">만화 컷 렌더링 시작</button>
            </div>
          </div>
        )}

        {currentStep === 'STEP_4_COMIC' && (
            <div className="space-y-8 animate-in fade-in duration-700">
                <div className="flex justify-center">
                  <button onClick={handleGenerateAllImages} disabled={isBusy || allImagesGenerated} className="px-10 py-5 bg-gradient-to-r from-teal-500 to-emerald-500 text-white font-black text-xl rounded-2xl shadow-xl shadow-teal-200 hover:scale-105 transition-all disabled:scale-100 disabled:grayscale">
                      {isGeneratingAllImages ? <><Spinner /><span className="ml-3">만화 완성 중...</span></> : '✨ 전체 4컷 생성'}
                  </button>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    {script?.panels.map((p, i) => (
                        <div key={i} className="group transition-all">
                          {textFrameStyle === 'speech-bubble' && rawImages[i] ? (
                              <InteractiveComicPanel rawImage={rawImages[i]!} panel={p} bubbleConfig={bubbleConfigs[i]!} onBubbleConfigChange={(cfg) => handleBubbleConfigChange(i, cfg)} />
                          ) : (
                              <ComicPanel panel={p} imageData={finalImages[i]} isLoading={generatingImageIndex === i} onGenerateImage={() => handleGenerateImage(i)} isScriptGenerated={true} />
                          )}
                        </div>
                    ))}
                </div>

                {allImagesGenerated && (
                    <div className="bg-white rounded-3xl p-10 shadow-2xl border border-slate-100 text-center space-y-6 animate-in slide-in-from-top-4 duration-500">
                        <h3 className="text-3xl font-title text-slate-800">🎉 학습 만화가 완성되었습니다!</h3>
                        <div className="flex justify-center gap-4 flex-wrap">
                            <button onClick={() => handleDownload('grid')} className="px-6 py-3 bg-slate-800 text-white font-bold rounded-xl hover:bg-black transition-colors">🖼️ 바둑판 저장</button>
                            <button onClick={() => handleDownload('vertical')} className="px-6 py-3 bg-slate-800 text-white font-bold rounded-xl hover:bg-black transition-colors">📱 모바일용 저장</button>
                            <button onClick={handleReset} className="px-6 py-3 bg-slate-200 text-slate-700 font-bold rounded-xl hover:bg-slate-300 transition-colors">처음부터 다시</button>
                        </div>
                    </div>
                )}
            </div>
        )}
      </main>

      <footer className="text-center mt-20 pt-10 border-t border-slate-100">
        <p className="text-slate-400 font-bold tracking-tight mb-2">Developed by <span className="text-orange-500">Zoops</span></p>
        <p className="text-xs text-slate-300">© 2025 AI Study Comic Tool. All Rights Reserved.</p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useCallback, useRef, useEffect } from 'react';
import { generateScript, generateImage, generateCharacterSheet, generateIdeas, generateInstagramPost, generateContinuationScript } from './services/geminiService';
import type { FullScript, Character } from './types';
import ComicPanel from './components/ComicPanel';
import Spinner from './components/Spinner';
import { InteractiveComicPanel, type BubbleConfig, drawTextOnImage, getDefaultBubbleConfig } from './components/InteractiveComicPanel';

// window.aistudio types for TypeScript
// Fix: All declarations of 'aistudio' must have identical modifiers and must be of type 'AIStudio'.
declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }

  interface Window {
    aistudio: AIStudio;
  }
}

const artStyles = [
  { name: '🧸 명랑만화', value: '명랑만화' },
  { name: '💥 아메리칸 코믹스', value: '아메리칸 코믹스' },
  { name: '✨ 한국 최신 웹툰', value: '한국 최신 웹툰' },
  { name: '🎞️ 린 클레어 (복고풍)', value: '린 클레어 (Ligne claire)' },
];

const textFrameStyles = [
  { id: 'speech-bubble', name: '💬 말풍선 (자유 편집)' },
  { id: 'simple', name: '⬜ 심플 (하단 흰색)' },
  { id: 'webtoon', name: '📱 웹툰 스타일' },
  { id: 'narration', name: '📜 나레이션 (상단)' },
  { id: 'cinematic', name: '🎬 시네마틱 자막' },
];

type Step = 'STEP_1_TOPIC' | 'STEP_2_SCRIPT' | 'STEP_3_CHARACTERS' | 'STEP_4_COMIC';
export type TailDirection =
  | 'top-left' | 'top-center' | 'top-right'
  | 'bottom-left' | 'bottom-center' | 'bottom-right'
  | 'left-top' | 'left-center' | 'left-bottom'
  | 'right-top' | 'right-center' | 'right-bottom';
export type StoryFormat = 'single' | 'serial';
export type ContinuationType = 'continue' | 'end';


const StepIndicator: React.FC<{ currentStep: Step }> = ({ currentStep }) => {
    const steps = [
        { id: 'STEP_1_TOPIC', title: '지문 입력' },
        { id: 'STEP_2_SCRIPT', title: '대본 확인' },
        { id: 'STEP_3_CHARACTERS', title: '캐릭터 생성' },
        { id: 'STEP_4_COMIC', title: '만화 완성' }
    ];
    const currentStepIndex = steps.findIndex(s => s.id === currentStep);

    return (
        <div className="flex justify-center items-center my-10 w-full max-w-2xl mx-auto px-4">
            {steps.map((step, index) => (
                <React.Fragment key={step.id}>
                    <div className="flex flex-col items-center relative">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm transition-all duration-300 ${index <= currentStepIndex ? 'bg-orange-500 text-white shadow-lg scale-110' : 'bg-slate-200 text-slate-500'}`}>
                            {index + 1}
                        </div>
                        <span className={`absolute -bottom-7 whitespace-nowrap text-xs font-semibold transition-colors duration-300 ${index <= currentStepIndex ? 'text-orange-600' : 'text-slate-400'}`}>{step.title}</span>
                    </div>
                    {index < steps.length - 1 && (
                        <div className={`flex-1 h-0.5 mx-2 transition-colors duration-500 ${index < currentStepIndex ? 'bg-orange-500' : 'bg-slate-200'}`}></div>
                    )}
                </React.Fragment>
            ))}
        </div>
    );
};

const App: React.FC = () => {
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);
  const [topic, setTopic] = useState<string>('');
  const [artStyle, setArtStyle] = useState<string>(artStyles[0].value);
  const [textFrameStyle, setTextFrameStyle] = useState<string>(textFrameStyles[0].id);
  const [script, setScript] = useState<FullScript | null>(null);

  const [rawImages, setRawImages] = useState<(string | null)[]>([null, null, null, null]);
  const [finalImages, setFinalImages] = useState<(string | null)[]>([null, null, null, null]);
  const [bubbleConfigs, setBubbleConfigs] = useState<(BubbleConfig | null)[]>([null, null, null, null]);

  const [isGeneratingScript, setIsGeneratingScript] = useState<boolean>(false);
  const [isGeneratingSheets, setIsGeneratingSheets] = useState<boolean>(false);
  const [generatingImageIndex, setGeneratingImageIndex] = useState<number | null>(null);
  const [isGeneratingAllImages, setIsGeneratingAllImages] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isGeneratingIdeas, setIsGeneratingIdeas] = useState<boolean>(false);
  const [suggestedIdeas, setSuggestedIdeas] = useState<string[]>([]);
  const [currentStep, setCurrentStep] = useState<Step>('STEP_1_TOPIC');

  const [storyFormat, setStoryFormat] = useState<StoryFormat>('single');
  const [continuationTopic, setContinuationTopic] = useState<string>('');
  const [isGeneratingContinuation, setIsGeneratingContinuation] = useState<boolean>(false);

  const characterImageInputRef = useRef<HTMLInputElement>(null);
  const [uploadTargetIndex, setUploadTargetIndex] = useState<number | null>(null);
  const [regeneratingSheetIndex, setRegeneratingSheetIndex] = useState<number | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        // Fallback for non-AI Studio environments
        setHasApiKey(true);
      }
    };
    checkKey();
  }, []);

  const handleConnectKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Assume selection successful as per guidelines to avoid race conditions
      setHasApiKey(true);
    }
  };

  const handleReset = () => {
    setTopic('');
    setScript(null);
    setRawImages([null, null, null, null]);
    setFinalImages([null, null, null, null]);
    setBubbleConfigs([null, null, null, null]);
    setIsGeneratingScript(false);
    setIsGeneratingSheets(false);
    setGeneratingImageIndex(null);
    setIsGeneratingAllImages(false);
    setError(null);
    setSuggestedIdeas([]);
    setCurrentStep('STEP_1_TOPIC');
    setContinuationTopic('');
    setIsGeneratingContinuation(false);
    setStoryFormat('single');
  };

  const handlePanelCharacterChange = useCallback((panelIndex: number, newCharacter: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, character: newCharacter };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
    setBubbleConfigs(prev => {
        const newConfigs = [...prev];
        const config = newConfigs[panelIndex];
        if (config) {
            newConfigs[panelIndex] = { ...config, style: newCharacter === '생각' ? 'thought' : 'speech' };
        }
        return newConfigs;
    });
  }, [script]);

  const handleDialogueChange = useCallback((panelIndex: number, newDialogue: string) => {
    if (!script) return;
    const updatedPanels = script.panels.map((panel, index) => {
        if (index === panelIndex) return { ...panel, dialogue: newDialogue };
        return panel;
    });
    setScript({ ...script, panels: updatedPanels });
  }, [script]);

  const handleBubbleConfigChange = useCallback((panelIndex: number, newConfig: BubbleConfig) => {
    setBubbleConfigs(prev => {
      const newConfigs = [...prev];
      newConfigs[panelIndex] = newConfig;
      return newConfigs;
    });
  }, []);

  const handleGenerateIdeas = useCallback(async () => {
    setIsGeneratingIdeas(true);
    setError(null);
    setSuggestedIdeas([]);
    try {
      const ideas = await generateIdeas();
      setSuggestedIdeas(ideas);
    } catch (err) {
      setError('아이디어를 가져오지 못했습니다.');
    } finally {
      setIsGeneratingIdeas(false);
    }
  }, []);

  const handleGenerateScript = useCallback(async () => {
    if (!topic.trim()) {
      setError('지문이나 학습 내용을 입력해주세요.');
      return;
    }
    setIsGeneratingScript(true);
    setError(null);
    try {
      const generatedScript = await generateScript(topic, storyFormat);
      setScript(generatedScript);
      setCurrentStep('STEP_2_SCRIPT');
    } catch (err) {
      if (err instanceof Error && err.message.includes("Requested entity was not found")) {
        setHasApiKey(false);
      }
      setError(err instanceof Error ? err.message : '대본 생성 중 오류가 발생했습니다.');
    } finally {
      setIsGeneratingScript(false);
    }
  }, [topic, storyFormat]);

  const handleGenerateCharacterSheets = useCallback(async () => {
    if (!script) return;
    setIsGeneratingSheets(true);
    setError(null);
    try {
        const sheetPromises = script.characters.map(char => 
            generateCharacterSheet(char.description, artStyle)
        );
        const sheetImages = await Promise.all(sheetPromises);
        const updatedCharacters = script.characters.map((char, index) => ({
            ...char,
            sheetImage: sheetImages[index],
        }));
        setScript({ ...script, characters: updatedCharacters });
        setCurrentStep('STEP_3_CHARACTERS');
    } catch (err) {
      if (err instanceof Error && err.message.includes("Requested entity was not found")) {
        setHasApiKey(false);
      }
      setError('캐릭터 생성에 실패했습니다.');
    } finally {
        setIsGeneratingSheets(false);
    }
  }, [script, artStyle]);

  const handleRegenerateCharacterSheet = useCallback(async (characterIndex: number) => {
    if (!script) return;
    setRegeneratingSheetIndex(characterIndex);
    try {
        const charToRegenerate = script.characters[characterIndex];
        const newSheetImage = await generateCharacterSheet(charToRegenerate.description, artStyle);
        setScript(prevScript => {
            if (!prevScript) return null;
            const updatedCharacters = prevScript.characters.map((char, index) => 
                index === characterIndex ? { ...char, sheetImage: newSheetImage } : char
            );
            return { ...prevScript, characters: updatedCharacters };
        });
    } catch (err) {
        setError('이미지 재생성 실패');
    } finally {
        setRegeneratingSheetIndex(null);
    }
  }, [script, artStyle]);


  const handleGenerateImage = useCallback(async (panelIndex: number) => {
    if (!script) return;
    setGeneratingImageIndex(panelIndex);
    try {
      const panel = script.panels[panelIndex];
      const rawImageBytes = await generateImage(panel.description, script.characters, artStyle);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = rawImageBytes;
          return newImages;
        });
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${rawImageBytes}`;
        tempImg.onload = () => {
          const tempCanvas = document.createElement('canvas');
          const tempCtx = tempCanvas.getContext('2d');
          if (tempCtx) {
            const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
            if (panel.character === '생각') defaultConfig.style = 'thought';
            setBubbleConfigs(prev => {
                const newConfigs = [...prev];
                newConfigs[panelIndex] = defaultConfig;
                return newConfigs;
            });
          }
        };
      } else {
        const imageWithText = await drawTextOnImage(rawImageBytes, panel, textFrameStyle);
        setFinalImages(prev => {
          const newImages = [...prev];
          newImages[panelIndex] = imageWithText;
          return newImages;
        });
      }
    } catch (err) {
      setError('이미지 생성 실패');
    } finally {
      setGeneratingImageIndex(null);
    }
  }, [script, artStyle, textFrameStyle]);

  const handleGenerateAllImages = useCallback(async () => {
    if (!script) return;
    setIsGeneratingAllImages(true);
    setError(null);
    try {
      const imageGenerationPromises = script.panels.map(panel => 
        generateImage(panel.description, script.characters, artStyle)
      );
      const generatedRawImages = await Promise.all(imageGenerationPromises);

      if (textFrameStyle === 'speech-bubble') {
        setRawImages(generatedRawImages);
        const tempImg = new Image();
        tempImg.src = `data:image/png;base64,${generatedRawImages[0]}`;
        tempImg.onload = () => {
            const tempCanvas = document.createElement('canvas');
            const tempCtx = tempCanvas.getContext('2d');
            if (tempCtx) {
                const newConfigs = script.panels.map(panel => {
                    const defaultConfig = getDefaultBubbleConfig(tempCtx, tempImg.width, tempImg.height, panel);
                    if (panel.character === '생각') defaultConfig.style = 'thought';
                    return defaultConfig;
                });
                setBubbleConfigs(newConfigs);
            }
        };
      } else {
        const processedImages = await Promise.all(
          generatedRawImages.map((rawImg, index) => 
            drawTextOnImage(rawImg, script.panels[index], textFrameStyle)
          )
        );
        setFinalImages(processedImages);
      }
    } catch (err) {
        setError('전체 생성 실패');
    } finally {
        setIsGeneratingAllImages(false);
    }
  }, [script, artStyle, textFrameStyle]);

  const getFinalImagesForDownload = useCallback(async (): Promise<(string | null)[]> => {
    if (textFrameStyle === 'speech-bubble') {
        return await Promise.all(rawImages.map(async (rawImg, index) => {
            if (!rawImg || !script || !bubbleConfigs[index]) return null;
            return await drawTextOnImage(rawImg, script.panels[index], textFrameStyle, bubbleConfigs[index]!);
        }));
    }
    return finalImages;
  }, [rawImages, finalImages, script, bubbleConfigs, textFrameStyle]);

  const handleDownload = useCallback(async (layout: 'grid' | 'horizontal' | 'vertical') => {
    const imagesToDownload = await getFinalImagesForDownload();
    if (!imagesToDownload.every(img => img)) { setError("완성되지 않은 컷이 있습니다."); return; }
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    const imageElements = await Promise.all(imagesToDownload.map(imgData => {
      return new Promise<HTMLImageElement>(res => {
        const img = new Image(); img.src = `data:image/png;base64,${imgData}`; img.onload = () => res(img);
      });
    }));
    const pw = imageElements[0].width; const ph = imageElements[0].height; const gap = 20;
    if (layout === 'grid') { canvas.width = pw * 2 + gap; canvas.height = ph * 2 + gap; }
    else if (layout === 'horizontal') { canvas.width = pw * 4 + gap * 3; canvas.height = ph; }
    else { canvas.width = pw; canvas.height = ph * 4 + gap * 3; }
    ctx.fillStyle = '#FFFFFF'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    if (layout === 'grid') {
      ctx.drawImage(imageElements[0], 0, 0); ctx.drawImage(imageElements[1], pw + gap, 0);
      ctx.drawImage(imageElements[2], 0, ph + gap); ctx.drawImage(imageElements[3], pw + gap, ph + gap);
    } else if (layout === 'horizontal') {
      imageElements.forEach((img, i) => ctx.drawImage(img, i * (pw + gap), 0));
    } else {
      imageElements.forEach((img, i) => ctx.drawImage(img, 0, i * (ph + gap)));
    }
    const link = document.createElement('a'); link.download = `comic-${layout}.png`; link.href = canvas.toDataURL('image/png'); link.click();
  }, [getFinalImagesForDownload]);

  const triggerCharacterImageUpload = (index: number) => {
    setUploadTargetIndex(index); characterImageInputRef.current?.click();
  };

  const onCharacterImageSelected = (event: React.ChangeEvent<HTMLInputElement>) => {
    if (uploadTargetIndex === null) return;
    const file = event.target.files?.[0];
    if (file) {
        const reader = new FileReader();
        reader.onloadend = () => {
            const base64String = (reader.result as string).split(',')[1];
            setScript(prev => {
                if (!prev) return null;
                const updated = [...prev.characters];
                updated[uploadTargetIndex] = { ...updated[uploadTargetIndex], sheetImage: base64String };
                return { ...prev, characters: updated };
            });
        };
        reader.readAsDataURL(file);
    }
    setUploadTargetIndex(null);
  };

  if (hasApiKey === null) {
    return <div className="flex items-center justify-center min-h-screen bg-[#f8fafc]"><Spinner /></div>;
  }

  if (hasApiKey === false) {
    return (
      <div className="flex flex-col items-center justify-center min-h-screen bg-[#f8fafc] p-6 text-center">
        <div className="bg-white p-12 rounded-[40px] shadow-2xl shadow-slate-200 border border-slate-100 max-w-lg animate-in fade-in zoom-in duration-500">
          <h1 className="text-5xl font-title text-orange-500 mb-6 tracking-tight">4컷 만화</h1>
          <p className="text-slate-600 mb-8 leading-relaxed">
            고품질 이미지 생성(Imagen 4)을 위해<br />
            <strong>결제가 설정된 Google Cloud 프로젝트</strong>의 API 키가 필요합니다.
          </p>
          <button 
            onClick={handleConnectKey}
            className="w-full py-5 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black text-xl rounded-2xl shadow-lg shadow-orange-200 hover:scale-105 transition-transform mb-6"
          >
            Google API 키 연결하기
          </button>
          <a 
            href="https://ai.google.dev/gemini-api/docs/billing" 
            target="_blank" 
            rel="noopener noreferrer"
            className="text-orange-500 text-sm font-bold hover:underline"
          >
            결제 및 API 키 설정 도움말 보기
          </a>
        </div>
      </div>
    );
  }

  const isBusy = isGeneratingScript || isGeneratingSheets || generatingImageIndex !== null || isGeneratingAllImages || isGeneratingIdeas || isGeneratingContinuation || regeneratingSheetIndex !== null;
  const allImagesGenerated = (rawImages.every(img => img !== null) || finalImages.every(img => img !== null));

  return (
    <div className="container mx-auto p-4 md:p-8 min-h-screen text-slate-800">
      <input type="file" ref={characterImageInputRef} accept="image/*" className="hidden" onChange={onCharacterImageSelected} />

      <header className="text-center mb-12">
        <h1 className="text-5xl md:text-7xl font-title text-orange-500 mb-4 tracking-tight">
          4컷 만화
        </h1>
        <p className="text-slate-500 text-lg font-medium">
          어려운 지문이나 학습 내용을 시각적으로 풀어내는 AI 도구
        </p>
      </header>

      <StepIndicator currentStep={currentStep} />

      <main className="max-w-4xl mx-auto">
        {error && (
          <div className="my-6 p-4 bg-red-50 border border-red-100 text-red-600 rounded-xl text-center font-medium shadow-sm animate-pulse">
            ⚠️ {error}
          </div>
        )}

        {currentStep === 'STEP_1_TOPIC' && (
            <div className="bg-white rounded-3xl shadow-xl shadow-slate-200/50 border border-slate-100 p-8 space-y-8">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2 px-1">그림 스타일</label>
                    <select value={artStyle} onChange={(e) => setArtStyle(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-orange-400 text-slate-700 appearance-none cursor-pointer">
                      {artStyles.map(s => <option key={s.value} value={s.value}>{s.name}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="block text-sm font-bold text-slate-700 mb-2 px-1">텍스트 디자인</label>
                    <select value={textFrameStyle} onChange={(e) => setTextFrameStyle(e.target.value)} className="w-full p-4 bg-slate-50 border-none rounded-2xl focus:ring-2 focus:ring-orange-400 text-slate-700 appearance-none cursor-pointer">
                      {textFrameStyles.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex justify-between items-end">
                    <label className="block text-sm font-bold text-slate-700 px-1">학습 지문 입력</label>
                    <button onClick={handleGenerateIdeas} disabled={isBusy} className="text-sm font-bold text-teal-600 hover:text-teal-700 flex items-center gap-1.5 transition-colors">
                        {isGeneratingIdeas ? <Spinner /> : "💡 구성 아이디어 추천"}
                    </button>
                  </div>

                  {suggestedIdeas.length > 0 && (
                    <div className="p-4 bg-teal-50/50 rounded-2xl border border-teal-100 flex flex-wrap gap-2">
                        {suggestedIdeas.map((idea, i) => (
                            <button key={i} onClick={() => setTopic(idea)} className="text-xs px-3 py-1.5 bg-white text-teal-700 rounded-full border border-teal-100 hover:border-teal-300 hover:shadow-sm transition-all">{idea}</button>
                        ))}
                    </div>
                  )}

                  <textarea
                    value={topic}
                    onChange={(e) => setTopic(e.target.value)}
                    placeholder="모의고사 지문이나 어려운 텍스트를 이곳에 붙여넣으세요. AI가 핵심 내용을 파악하여 만화로 그려줍니다."
                    className="w-full p-6 bg-slate-50 border-none rounded-3xl focus:ring-2 focus:ring-orange-400 transition-all resize-none min-h-[200px] text-slate-700 leading-relaxed placeholder:text-slate-400"
                    disabled={isBusy}
                  />
                </div>

                <button
                  onClick={handleGenerateScript}
                  disabled={isBusy}
                  className="w-full py-5 bg-gradient-to-r from-orange-500 to-orange-600 text-white font-black text-xl rounded-2xl shadow-lg shadow-orange-200 hover:shadow-orange-300 transition-all transform hover:-translate-y-1 active:translate-y-0 disabled:grayscale flex items-center justify-center gap-3"
                >
                  {isGeneratingScript ? <Spinner /> : '🚀 학습 대본 생성하기'}
                </button>
            </div>
        )}

        {currentStep === 'STEP_2_SCRIPT' && script && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-500">
              <h3 className="text-3xl font-title text-slate-800 text-center">대본 검토</h3>
              <div className="grid gap-6">
                {script.panels.map((p, i) => (
                    <div key={i} className="p-6 bg-slate-50 rounded-3xl border border-slate-100 group transition-all hover:border-orange-200">
                        <div className="flex justify-between items-center mb-4">
                          <span className="px-3 py-1 bg-orange-100 text-orange-600 text-xs font-black rounded-full uppercase tracking-widest">Panel {p.panel}</span>
                        </div>
                        <p className="text-sm text-slate-500 mb-4 bg-white p-4 rounded-2xl border border-slate-100 leading-relaxed">
                          <strong className="text-slate-700 mr-2">이미지 가이드:</strong> {p.description}
                        </p>
                        <div className="flex gap-4">
                            <input value={p.character} onChange={(e) => handlePanelCharacterChange(i, e.target.value)} className="w-32 p-3 bg-white border-none rounded-xl font-bold text-sm focus:ring-2 focus:ring-orange-400 shadow-sm" placeholder="화자" />
                            <textarea value={p.dialogue} onChange={(e) => handleDialogueChange(i, e.target.value)} className="w-full p-3 bg-white border-none rounded-xl text-sm focus:ring-2 focus:ring-orange-400 shadow-sm" rows={2} placeholder="대사" />
                        </div>
                    </div>
                ))}
              </div>
              <div className="flex flex-col md:flex-row gap-4 pt-4">
                  <button onClick={() => setCurrentStep('STEP_1_TOPIC')} className="flex-1 py-4 bg-slate-100 text-slate-600 font-bold rounded-2xl hover:bg-slate-200 transition-all">수정하기</button>
                  <button onClick={handleGenerateCharacterSheets} disabled={isBusy} className="flex-[2] py-4 bg-orange-500 text-white font-black rounded-2xl shadow-lg shadow-orange-200 flex items-center justify-center gap-2">
                      {isGeneratingSheets ? <Spinner /> : '🎨 캐릭터 일러스트 생성'}
                  </button>
              </div>
          </div>
        )}

        {currentStep === 'STEP_3_CHARACTERS' && script?.characters && (
          <div className="bg-white rounded-3xl shadow-xl border border-slate-100 p-8 space-y-10 animate-in fade-in zoom-in duration-500">
            <h3 className="text-3xl font-title text-slate-800 text-center">학습 만화 주인공</h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-8">
              {script.characters.map((char, i) => (
                <div key={i} className="flex flex-col items-center group">
                  <div className="relative w-40 h-40 mb-6 group">
                    <div className="absolute inset-0 bg-orange-500 rounded-full blur-xl opacity-0 group-hover:opacity-20 transition-opacity"></div>
                    {regeneratingSheetIndex === i ? (
                      <div className="w-full h-full bg-slate-50 rounded-full flex items-center justify-center border-4 border-slate-100"><Spinner /></div>
                    ) : (
